const { diag, DiagConsoleLogger, DiagLogLevel } = require("@opentelemetry/api");
const tracer = require("./tracing");
const {
  BUFFER_TIMEOUT,
  MAX_EXPORT_BATCH_SIZE,
  PRODUCT,
} = require("./constants");
const { toLowerCase, normalizeSet } = require("./utils.js");
const MiddlewareRecorder = require("./recording");
const {
  DEFAULT_RAGE_CLICK_THRESHOLD_PX,
  DEFAULT_RAGE_CLICK_TIMEOUT_MS,
  DEFAULT_RAGE_CLICK_CLICK_COUNT,
  DEFAULT_RAGE_CLICK_INTERACTIVE_ELEMENTS_ONLY,
} = require("./rageClick");
const { DEFAULT_DEAD_CLICK_TIMEOUT_MS } = require("./deadClick");

const configDefault = {
  accountKey: "",
  env: "prod",
  target: "",
  DEBUG: DiagLogLevel.NONE,
  cookieDomain: undefined,
  projectName: window.location.host,
  serviceName: "web-app",
  recording: "1",
  defaultAttributes: {
    username: "Anonymous",
  },
  tracer: {},
  pageTracking: true,
  trackSubmit: true,
  scrollCheckpoints: [25, 50, 75, 100],
  bufferSize: MAX_EXPORT_BATCH_SIZE,
  bufferTimeout: BUFFER_TIMEOUT,
  recordingOptions: {
    maskSensitiveInputs: true,
    maskInputSelectors: [],
    maskAllInputs: false,
    maskTextClass: "mw-mask",
    blockClass: "mw-block",
    ignoreClass: "mw-ignore",
    mutationRateLimiter: true,
    mutationBucketSize: 100,
    mutationRefillRate: 10,
  },
  deadClick: {
    timeout_ms: DEFAULT_DEAD_CLICK_TIMEOUT_MS,
  },
  rageClick: {
    timeout_ms: DEFAULT_RAGE_CLICK_TIMEOUT_MS,
    threshold_px: DEFAULT_RAGE_CLICK_THRESHOLD_PX,
    click_count: DEFAULT_RAGE_CLICK_CLICK_COUNT,
    interactive_elements_only: DEFAULT_RAGE_CLICK_INTERACTIVE_ELEMENTS_ONLY,
  },
  console: true,
  consoleRateLimit: 100,
  errors: true,
  blockBotTraffic: true,
  advanceNetworkCapture: false,
  websocket: false,
  ignoreUrls: [],
  ignoreHeaders: new Set([]),
  tracePropagationTargets: [/.*/],
  disableNetworkInstrumentation: false,
  webVitals: true,
  scheduledDelayMillis: 5000,
  longtask: true,
  sdkMetrics: false,
  vcsCommitSHA: undefined,
  vcsRepositoryURL: undefined,
};

const normalizeDefaultAttributes = (attributes) => {
  const normalized = { ...(attributes || {}) };
  if ("name" in normalized) {
    if (!("username" in normalized)) {
      normalized.username = normalized.name;
    }
    delete normalized.name;
  }
  if (!normalized.username) {
    normalized.username = "Anonymous";
  }
  return normalized;
};

module.exports.normalizeDefaultAttributes = normalizeDefaultAttributes;

module.exports.init = (config = {}) => {
  const initFromMergedConfig = () => {
    Object.keys(configDefault).forEach((key) => {
      if (key === "defaultAttributes") {
        config[key] = normalizeDefaultAttributes(config[key]);
        configDefault[key] = config[key];
      } else if (key === "ignoreHeaders" && config[key]) {
        configDefault[key] = normalizeSet(new Set(config[key]), toLowerCase);
      } else {
        configDefault[key] = key in config ? config[key] : configDefault[key];
      }
    });
    if (configDefault.target) {
      configDefault.target = new URL(configDefault.target).origin;
    }
    diag.setLogger(
      new DiagConsoleLogger(),
      configDefault["DEBUG"] ? DiagLogLevel.DEBUG : DiagLogLevel.NONE
    );
    tracer.init(configDefault);
  };

  //Fetch from api
  fetch(
    `${config.target}/api/v1/agent/ingestion-rules/${config.accountKey}?platform=rum`
  )
    .then((res) => {
      if (!res.ok) {
        initFromMergedConfig();
        return;
      }
      return res.text().then((text) => {
        const trimmed = (text || "").trim();
        if (!trimmed) {
          initFromMergedConfig();
          return;
        }
        let data;
        try {
          data = JSON.parse(trimmed);
        } catch {
          initFromMergedConfig();
          return;
        }
        if (
          config.projectName !==
          data?.["rum_config"]?.["meta_data"]?.["RawMessage"]?.["name"]
        ) {
          console.error(
            `[Middleware] Application name is mismatch. Please update the application name to ${config.projectName} in installation page.`
          );
          return;
        }

        Object.keys(configDefault).forEach((key) => {
          if (key === "defaultAttributes") {
            config[key] = normalizeDefaultAttributes(config[key]);
            configDefault[key] = config[key];
          } else if (key === "ignoreHeaders" && config[key]) {
            configDefault[key] = normalizeSet(
              new Set(config[key]),
              toLowerCase
            );
          } else if (key === "recordingOptions") {
            configDefault[key] = {
              ...configDefault[key],
              ...(key in config ? config[key] : {}),
            };
          } else {
            configDefault[key] =
              key in config ? config[key] : configDefault[key];
          }
        });
        const defaultRecordingOptions = configDefault.recordingOptions;
        if (
          data?.["rum_config"]?.["meta_data"]?.["RawMessage"]?.[
            "recordingOptions"
          ]
        ) {
          configDefault.recordingOptions =
            data?.["rum_config"]?.["meta_data"]?.["RawMessage"]?.[
              "recordingOptions"
            ];
          if (!configDefault.recordingOptions.blockClass) {
            configDefault.recordingOptions.blockClass =
              defaultRecordingOptions.blockClass || "mw-block";
          }
          if (!configDefault.recordingOptions.ignoreClass) {
            configDefault.recordingOptions.ignoreClass =
              defaultRecordingOptions.ignoreClass || "mw-ignore";
          }
          if (!configDefault.recordingOptions.maskAllInputs) {
            configDefault.recordingOptions.maskAllInputs =
              defaultRecordingOptions.maskAllInputs || false;
          }
          if (!configDefault.recordingOptions.maskSensitiveInputs) {
            configDefault.recordingOptions.maskSensitiveInputs =
              defaultRecordingOptions.maskSensitiveInputs === false
                ? false
                : true;
          }
          if (!configDefault.recordingOptions.maskTextClass) {
            configDefault.recordingOptions.maskTextClass =
              defaultRecordingOptions.maskTextClass || "mw-mask";
          }
          if (!configDefault.recordingOptions.maskInputSelectors) {
            configDefault.recordingOptions.maskInputSelectors =
              defaultRecordingOptions.maskInputSelectors || [];
          } else {
            configDefault.recordingOptions.maskInputSelectors =
              configDefault.recordingOptions.maskInputSelectors.map((item) => {
                return item.trim();
              });
          }
          if (Array.isArray(configDefault.recordingOptions.maskTextClass)) {
            configDefault.recordingOptions.maskTextClass.push("mw-mask");

            const maskTextClassString =
              configDefault.recordingOptions.maskTextClass.map((item) => {
                return item.trim();
              });
            configDefault.recordingOptions.maskTextClass = new RegExp(
              maskTextClassString.join("|"),
              "gm"
            );
          } else {
            configDefault.recordingOptions.maskTextClass = "mw-mask";
          }
          if(!configDefault.recordingOptions.mutationRateLimiter) {
            configDefault.recordingOptions.mutationRateLimiter = defaultRecordingOptions.mutationRateLimiter;
          }
          if(!configDefault.recordingOptions.mutationBucketSize) {
            configDefault.recordingOptions.mutationBucketSize = defaultRecordingOptions.mutationBucketSize;
          }
          if(!configDefault.recordingOptions.mutationRefillRate) {
            configDefault.recordingOptions.mutationRefillRate = defaultRecordingOptions.mutationRefillRate;
          }
        } else {
          configDefault.recordingOptions = defaultRecordingOptions;
        }

        if (
          data?.["rum_config"]?.["meta_data"]?.["RawMessage"]?.[
            "disableTracePropagation"
          ] !== true
        ) {
          if (
            data?.["rum_config"]?.["meta_data"]?.["RawMessage"]?.[
              "tracePropagationTargets"
            ]?.length > 0
          ) {
            configDefault.tracePropagationTargets = data["rum_config"][
              "meta_data"
            ]["RawMessage"]["tracePropagationTargets"].map(
              (value) => new RegExp(value, "i")
            );
          }
        } else {
          configDefault.tracePropagationTargets = [];
        }

        if (
          data?.["rum_config"]?.["meta_data"]?.["RawMessage"]?.[
            "disableNetworkInstrumentation"
          ] !== undefined
        ) {
          configDefault.disableNetworkInstrumentation =
            data["rum_config"]["meta_data"]["RawMessage"][
              "disableNetworkInstrumentation"
            ];
        }

        if (
          data?.["rum_config"]?.["meta_data"]?.["RawMessage"]?.["recording"] !==
          undefined
        ) {
          configDefault.recording = data["rum_config"]["meta_data"][
            "RawMessage"
          ]["recording"]
            ? "1"
            : "0";
        }

        if (
          data?.["rum_config"]?.["meta_data"]?.["RawMessage"]?.["errors"] !==
          undefined
        ) {
          configDefault.errors =
            data["rum_config"]["meta_data"]["RawMessage"]["errors"];
        }
        if (
          data?.["rum_config"]?.["meta_data"]?.["RawMessage"]?.["console"] !==
          undefined
        ) {
          configDefault.console =
            data["rum_config"]["meta_data"]["RawMessage"]["console"];
        }

        if (
          data?.["rum_config"]?.["meta_data"]?.["RawMessage"]?.[
            "advanceNetworkCapture"
          ] !== undefined
        ) {
          configDefault.advanceNetworkCapture =
            data["rum_config"]["meta_data"]["RawMessage"][
              "advanceNetworkCapture"
            ];
        }

        if (
          data?.["rum_config"]?.["meta_data"]?.["RawMessage"]?.["websocket"] !==
          undefined
        ) {
          configDefault.websocket =
            data["rum_config"]["meta_data"]["RawMessage"]["websocket"];
        }

        if (
          data?.["rum_config"]?.["meta_data"]?.["RawMessage"]?.["sdkMetrics"] !==
          undefined
        ) {
          configDefault.sdkMetrics =
            data["rum_config"]["meta_data"]["RawMessage"]["sdkMetrics"];
        }

        if (
          data?.["rum_config"]?.["meta_data"]?.["RawMessage"]?.["webVitals"] !==
          undefined
        ) {
          configDefault.webVitals =
            data?.["rum_config"]["meta_data"]["RawMessage"]["webVitals"];
        }

        if (
          data?.["rum_config"]["meta_data"]["RawMessage"]["longtask"] !==
          undefined
        ) {
          configDefault.longtask =
            data["rum_config"]["meta_data"]["RawMessage"]["longtask"];
        }

        if (
          (configDefault.vcsCommitSHA === undefined ||
            configDefault.vcsCommitSHA === "undefined" ||
            configDefault.vcsCommitSHA === "") &&
          data?.["rum_config"]?.["meta_data"]?.["RawMessage"]?.["vcsCommitSHA"]
        ) {
          configDefault.vcsCommitSHA =
            data["rum_config"]["meta_data"]["RawMessage"]["vcsCommitSHA"];
        }

        if (
          (configDefault.vcsRepositoryURL === undefined ||
            configDefault.vcsRepositoryURL === "undefined" ||
            configDefault.vcsRepositoryURL === "") &&
          data?.["rum_config"]?.["meta_data"]?.["RawMessage"]?.[
            "vcsRepositoryURL"
          ]
        ) {
          configDefault.vcsRepositoryURL =
            data["rum_config"]["meta_data"]["RawMessage"]["vcsRepositoryURL"];
        }

        if (configDefault.target) {
          configDefault.target = new URL(configDefault.target).origin;
        }
        diag.setLogger(
          new DiagConsoleLogger(),
          configDefault["DEBUG"] ? DiagLogLevel.DEBUG : DiagLogLevel.NONE
        );

        tracer.init(configDefault);
      });
    })
    .catch(() => {
      initFromMergedConfig();
    });

  return { ...configDefault, ...config };
};

module.exports.setAttributes = (attributes = {}) => {
  const normalized = { ...attributes };
  if ("name" in normalized) {
    if (!("username" in normalized)) {
      normalized.username = normalized.name;
    }
    delete normalized.name;
  }
  tracer.setAttributes(normalized);
};
module.exports.addAction = (action, attributes = {}) => {
  tracer.addAction(action, attributes);
};
module.exports.getTracer = (name) => {
  return tracer.getTracer(name);
};

module.exports.getSessionId = () => {
  return tracer.getSessionId();
};

module.exports.info = (msg) => {
  tracer.recordLog("info", msg);
};
module.exports.warn = (msg) => {
  tracer.recordLog("warn", msg);
};
module.exports.debug = (msg) => {
  tracer.recordLog("debug", msg);
};
module.exports.error = (msg) => {
  tracer.recordLog("error", msg);
};

module.exports.stopVideoRecording = () => {
  MiddlewareRecorder.stop();
};

module.exports.resumeVideoRecording = () => {
  MiddlewareRecorder.resume();
};

module.exports.deinit = () => {
  tracer.deinit();
  if (diag) {
    diag.disable();
  }
};
