"use strict";
const rrweb = require("rrweb");
const RRWebExporter = require("./RRWebExporter");
const RRWebProcessor = require("./RRWebProcessor");
const { getRumSessionId } = require("./session");
const {
  MutationRateLimiter,
  DEFAULT_OBFUSCATE_REGEXES,
  MASK_VALUE,
} = require("./sessionRecordingUtils");
const { VERSION } = require("./version");
const { trace } = require("@opentelemetry/api");
const sdkMetrics = require("./sdk-metrics");

const MAX_RECORDING_LENGTH = 4 * 60 * 60 * 1000;
let previousSessionId;
let sessionStartTime = 0;
let inited = false;
let queuedFullSnapshotTimeout;
let tracer;
let paused = false;
let debugEnabled = false;
let lastConfig;
let lastProvider;
let lastResource;
let pendingVisibilityHandler = null;
let processor;

/**
 * True when `candidate` is a real SDK tracer provider rather than the API's
 * no-op or the proxy that stands in before the SDK registers.
 *
 * This used to look for a `resource` property, which SDK 2.x removed from the
 * provider's public surface -- it keeps the resource privately now, so that
 * check silently reported "not inited" for every page and recording never
 * started. `forceFlush` is part of the SDK provider contract in both 1.x and
 * 2.x and is absent from the no-op and proxy providers, so it tells them apart
 * without reaching for internals.
 */
const isSdkTracerProvider = (candidate) =>
  Boolean(candidate) && typeof candidate.forceFlush === "function";

/** Unwraps the global provider down to whatever the SDK registered. */
const resolveGlobalTracerProvider = () => {
  let provider = trace.getTracerProvider();
  if (provider && "getDelegate" in provider) {
    provider = provider.getDelegate();
  }
  return provider;
};

// rrweb throws when a snapshot is requested before the document is ready.
const takeFullSnapshotSafely = () => {
  try {
    if (debugEnabled) {
      console.log("Taking full snapshot...");
    }
    rrweb.record.takeFullSnapshot();
  } catch (error) {
    if (debugEnabled) {
      console.error(error);
    }
  }
};

// Session ids rotate mid-page (idle timeout, 4h cap) and nothing else restarts the
// recorder, so re-arm here or the new id has no FullSnapshot and cannot be replayed.
const applySessionRotation = () => {
  previousSessionId = getRumSessionId();
  sessionStartTime = Date.now();
  sdkMetrics.recordSessionRotated();
  if (paused) {
    return;
  }
  takeFullSnapshotSafely();
};

// A hidden tab cannot produce a usable snapshot; wait for it to come back rather than
// dropping every frame until rrweb happens to emit while visible.
const snapshotWhenVisible = () => {
  if (pendingVisibilityHandler) {
    return;
  }
  const handler = () => {
    if (document.hidden) {
      return;
    }
    document.removeEventListener("visibilitychange", handler);
    if (pendingVisibilityHandler === handler) {
      pendingVisibilityHandler = null;
    }
    applySessionRotation();
  };
  pendingVisibilityHandler = handler;
  document.addEventListener("visibilitychange", handler);
};

const clearPendingVisibilityHandler = () => {
  if (!pendingVisibilityHandler) {
    return;
  }
  document.removeEventListener("visibilitychange", pendingVisibilityHandler);
  pendingVisibilityHandler = null;
};

const MiddlewareRecorder = {
  get inited() {
    return Boolean(inited);
  },
  init(config, provider, resource) {
    // Kept before the guards so a session rotation can retry an init that bailed.
    lastConfig = config;
    lastProvider = provider;
    lastResource = resource;
    if (inited) {
      return;
    }

    // tracing.init() hands its provider in directly; the global lookup is the
    // fallback for a caller that did not.
    if (
      !isSdkTracerProvider(provider) &&
      !isSdkTracerProvider(resolveGlobalTracerProvider())
    ) {
      console.error("RUM OTEL Web must be inited before recorder.");
      return;
    }
    tracer = trace.getTracer("rum.rr-web", VERSION);
    const span = tracer.startSpan("record init");

    // Check if sampler is ignoring this
    if (!span.isRecording()) {
      return;
    }
    span.end();

    previousSessionId = Middleware.getSessionId();
    sessionStartTime = Date.now();
    const exporter = new RRWebExporter(config, provider, resource);
    processor = new RRWebProcessor(exporter, config);
    const url = new URL(window.location.href);
    const debug = url.searchParams.get("debug");
    debugEnabled = debug === "true";
    const mutationRateLimiter = config.recordingOptions.mutationRateLimiter
      ? new MutationRateLimiter(rrweb.record, {
          bucketSize: config.recordingOptions.mutationBucketSize ?? 100,
          refillRate: config.recordingOptions.mutationRefillRate ?? 10,
          onBlockedNode: (id, node) => {
            const message = `OpenTelemetry Session Recorder: Rate limiting recording mutations on node ${id}. This can be due to excessive animations.`;

            if (debug === "true") {
              console.warn(message, node);
            }

            sdkMetrics.recordMutationThrottled();

            clearTimeout(queuedFullSnapshotTimeout);
            queuedFullSnapshotTimeout = setTimeout(() => {
              // Take a full snapshot to capture more accurate final mutation state
              // This is only fired once per node, so we can still miss the outcome
              // of repeated mutations
              rrweb.record.takeFullSnapshot();
            }, 1000);
          },
        })
      : null;
    if (debug === "true") {
      console.log(
        "Mutation Rate Limiter enabled:",
        Boolean(mutationRateLimiter)
      );
    }
    inited = rrweb.record({
      recordCrossOriginIframes: true,
      inlineStylesheet: true,
      maskAllInputs:
        config.recordingOptions.maskAllInputs ||
        config.recordingOptions.maskSensitiveInputs,
      maskInputFn: (input, element) => {
        if (config.recordingOptions.maskSensitiveInputs) {
          if (DEFAULT_OBFUSCATE_REGEXES.some((regex) => regex.test(input))) {
            return MASK_VALUE;
          }
        } else if (config.recordingOptions.maskAllInputs) {
          return MASK_VALUE;
        }
        if (config.recordingOptions.maskInputSelectors.length > 0) {
          const selector = config.recordingOptions.maskInputSelectors.find(
            (selector) => element.matches(selector)
          );
          if (selector) {
            return MASK_VALUE;
          }
        }
        return input;
      },
      ...config.recordingOptions,
      emit(event) {
        // Checked before `paused` so a paused recorder still tracks the rotation and
        // resume() starts the new session from a correct sessionStartTime.
        if (getRumSessionId() !== previousSessionId) {
          if (document.hidden) {
            snapshotWhenVisible();
            sdkMetrics.recordRecordingDropped("hidden");
            return;
          }
          applySessionRotation();
        }

        if (paused) {
          sdkMetrics.recordRecordingDropped("paused");
          return;
        }

        if (event.timestamp > sessionStartTime + MAX_RECORDING_LENGTH) {
          sdkMetrics.recordRecordingDropped("max_length");
          return;
        }

        event = mutationRateLimiter
          ? mutationRateLimiter.throttleMutations(event)
          : event;

        if (!event) {
          return;
        }
        processor.onMetric(event);
      },
      sampling: {
        scroll: 150,
        media: 800,
        input: "last",
        mousemove: 500,
      },
    });
  },
  // Called from tracing.js when session.js mints a new session id mid-page.
  onSessionRotate() {
    if (!inited) {
      // init() bailed at page load; the sampler re-decides per session id, so the
      // new one gets its own chance at a recorder.
      if (lastConfig) {
        MiddlewareRecorder.init(lastConfig, lastProvider, lastResource);
      }
      return;
    }
    if (getRumSessionId() === previousSessionId) {
      return;
    }
    if (document.hidden) {
      snapshotWhenVisible();
      return;
    }
    applySessionRotation();
  },
  setCustomEvent(eventName, eventAttributes) {
    if (!inited) {
      return;
    }
    try {
      rrweb.record.addCustomEvent(eventName, eventAttributes);
    } catch (error) {
      // Throws custom event error, ignoring the error
    }
  },
  stop() {
    if (!inited) {
      return;
    }
    if (!paused) {
      tracer.startSpan("record stop").end();
    }
    paused = true;
  },
  resume() {
    if (!inited) {
      return;
    }
    const wasPaused = paused;
    paused = false;
    if (wasPaused) {
      takeFullSnapshotSafely();
      tracer.startSpan("record resume").end();
    }
  },
  deinit() {
    if (!inited) {
      return;
    }

    clearPendingVisibilityHandler();
    inited();
    inited = false;
    processor.shutdown();
    processor = undefined;
  },
};

module.exports = MiddlewareRecorder;
