const {
  XMLHttpRequestInstrumentation,
} = require("@opentelemetry/instrumentation-xml-http-request");
const shimmer = require("shimmer");
const { headerCapture, captureTraceParent } = require("./utils/httpUtils");
const { setResourceTimingAttributes } = require("./utils/resourceTiming.js");
const { SpanStatusCode } = require("@opentelemetry/api");

class MiddlewareXHRInstrumentaion extends XMLHttpRequestInstrumentation {
  config = {};

  constructor(config = {}) {
    super(config);
    this.config = config;
  }

  _createSpan(xhr, url, method) {
    const span = super._createSpan(xhr, url, method);
    const ignoreHeaders = this.config.ignoreHeaders;
    if (span) {
      if (this.config.advanceNetworkCapture) {
        xhr.addEventListener("readystatechange", function () {
          if (xhr.readyState === xhr.OPENED) {
            shimmer.wrap(xhr, "setRequestHeader", (original) => {
              return function (header, value) {
                headerCapture(
                  "request",
                  [header],
                  ignoreHeaders
                )(span, () => value);
                return original.apply(this, arguments);
              };
            });
            shimmer.wrap(xhr, "send", (original) => {
              return function (body) {
                if (body) {
                  span.setAttribute("http.request.body", body.toString());
                }
                return original.apply(this, arguments);
              };
            });
          } else if (xhr.readyState === xhr.DONE) {
            const headers = xhr
              .getAllResponseHeaders()
              .split("\r\n")
              .reduce((result, current) => {
                let [name, value] = current.split(": ");
                if (name && value) {
                  result[name] = value;
                }
                return result;
              }, {});
            headerCapture(
              "response",
              Object.keys(headers),
              ignoreHeaders
            )(span, (header) => headers[header]);
            try {
              span.setAttribute("http.response.body", xhr.responseText);
            } catch (e) {
              // ignore (DOMException if responseType is not the empty string or "text")
            }

            shimmer.unwrap(xhr, "setRequestHeader");
            shimmer.unwrap(xhr, "send");
          }
        });
        xhr.addEventListener("readystatechange", function () {
          if (xhr.readyState === xhr.HEADERS_RECEIVED) {
            const headers = xhr.getAllResponseHeaders().toLowerCase();
            if (headers.indexOf("server-timing") !== -1) {
              const st = xhr.getResponseHeader("server-timing");
              if (st !== null) {
                captureTraceParent(st, span);
              }
            }
          }
        });
      }
    }
    return span;
  }
  _addFinalSpanAttributes(span, xhrMem) {
    if (
      xhrMem &&
      xhrMem.createdResources &&
      xhrMem.createdResources.entries &&
      xhrMem.createdResources.entries.length > 0
    ) {
      const resource = xhrMem.createdResources.entries[0];
      if (resource) {
        setResourceTimingAttributes(span, resource);
      }
    }

    if (xhrMem.status && xhrMem.status >= 400) {
      span.setStatus({ code: SpanStatusCode.ERROR });
    }
    span.setAttribute("resource.type", "xhr");
    return super._addFinalSpanAttributes(span, xhrMem);
  }
}

module.exports = MiddlewareXHRInstrumentaion;
