const {
  SpanKind,
  context,
  trace,
  SpanStatusCode,
} = require("@opentelemetry/api");
const { InstrumentationBase } = require("@opentelemetry/instrumentation");
const shimmer = require("shimmer");
const ErrorStackParser = require("./utils/error-stack-parser");
const {
  limitLen,
  STACK_LIMIT,
  MESSAGE_LIMIT,
} = require("./logs-instrumentation");
const { isUrlIgnored } = require("@opentelemetry/core");
const { jsonToString, getExceptionStackFrames } = require("./utils");
const { setUrlAttributes } = require("./utils/httpUtils");

function size(o) {
  return o.byteLength || o.size || o.length || undefined;
}

class MiddlewareWebSocketInstrumentation extends InstrumentationBase {
  listener2ws2patched = new WeakMap();
  _config = {};
  constructor(config = {}) {
    super("middleware-websocket-instrumentation", "1.0.0", config);
    this._config = config;
  }

  init() {}

  enable() {
    const instrumentation = this;
    function websocketWrapper() {
      class InstrumentWebsocket extends WebSocket {
        constructor(url, protocols) {
          if (isUrlIgnored(url, instrumentation._config.ignoreUrls)) {
            super(url, protocols);
            return;
          }

          const connectSpan = instrumentation.tracer.startSpan("connect", {
            kind: SpanKind.CLIENT,
            attributes: {
              component: "websocket",
              "event.type": "websocket",
            },
          });
          if (url) {
            connectSpan.setAttribute("http.url", url);
            setUrlAttributes(connectSpan, url);
          }
          if (protocols) {
            if (typeof protocols === "string") {
              connectSpan.setAttribute("protocols", protocols);
            } else {
              connectSpan.setAttribute("protocols", JSON.stringify(protocols));
            }
          }
          try {
            super(url, protocols);
          } catch (error) {
            instrumentation.endSpanExceptionally(
              connectSpan,
              constructorException
            );
            throw constructorException;
          }

          this.addEventListener("open", () => {
            connectSpan.end();
          });
          this.addEventListener("error", (event) => {
            if (connectSpan.isRecording()) {
              instrumentation.endSpanExceptionally(
                connectSpan,
                new Error(
                  event.error || event.message || "Websocker could not connect."
                )
              );
            } else {
              instrumentation.startSpan(this, "error", SpanKind.CLIENT).end();
            }
          });
          instrumentation.patchSend(this);
          instrumentation.patchEventListener(this);
        }
      }
      return InstrumentWebsocket;
    }
    shimmer.wrap(window, "WebSocket", websocketWrapper);
  }

  disable() {
    shimmer.unwrap(window, "WebSocket");
  }

  startSpan(ws, name, spanKind) {
    const span = this.tracer.startSpan(name, {
      kind: spanKind,
    });
    span.setAttribute("component", "websocket");
    span.setAttribute("event.type", "websocket");
    span.setAttribute("http.url", ws.url);
    setUrlAttributes(span, ws.url);
    span.setAttribute("protocol", ws.protocol);
    return span;
  }

  patchSend(ws) {
    const instrumentation = this;
    const originalSend = ws.send;
    ws.send = function instrumentSend(...args) {
      const span = instrumentation.startSpan(ws, "send", SpanKind.PRODUCER);
      const sendSize = args.length > 0 ? size(args[0]) : undefined;
      span.setAttribute("http.request_content_length", sendSize);
      let retVal = undefined;

      try {
        retVal = originalSend.apply(ws, args);
      } catch (error) {
        instrumentation.endSpanExceptionally(span, error);
        throw error;
      }

      if (retVal === false) {
        instrumentation.endSpanExceptionally(
          span,
          new Error("Websocket failed to send message.")
        );
      }
      span.end();
      return retVal;
    };
  }

  addPatchListener(ws, origListener, patched) {
    let ws2patched = this.listener2ws2patched.get(origListener);
    if (!ws2patched) {
      ws2patched = new Map();
      this.listener2ws2patched.set(origListener, ws2patched);
    }
    if (ws2patched.has(ws)) {
      return false;
    }
    ws2patched.set(ws, patched);
    return true;
  }

  removePatchListener(ws, origListener) {
    const ws2patched = this.listener2ws2patched.get(origListener);
    if (!ws2patched) {
      return undefined;
    }
    const patched = ws2patched.get(ws);
    if (patched) {
      ws2patched.delete(ws);
      if (ws2patched.size === 0) {
        this.listener2ws2patched.delete(origListener);
      }
    }
    return patched;
  }

  patchEventListener(ws) {
    const instrumentation = this;
    const origAEL = ws.addEventListener.bind(ws);

    ws.addEventListener = function instrumentAddEventListener(
      type,
      callback,
      options = undefined
    ) {
      if (type !== "message") {
        // only patching message event listeners
        origAEL(type, callback, options);
        return;
      }

      const once = typeof options === "boolean" ? undefined : options?.once;
      const patchedCallback = function patchedAddEventListenerCallback(
        ...args
      ) {
        const capturedThiz = this;
        const capturedArgs = args;
        if (once) {
          instrumentation.removePatchListener(ws, callback);
        }
        const span = instrumentation.startSpan(
          ws,
          "onmessage",
          SpanKind.CONSUMER
        );
        if (capturedArgs && capturedArgs[0] && capturedArgs[0].data) {
          span.setAttribute(
            "http.response_content_length",
            size(capturedArgs[0].data)
          );
        }
        // FIXME fill out message details, size, etc.
        context.with(trace.setSpan(context.active(), span), () => {
          let result = undefined;
          if (typeof callback === "function") {
            result = callback.apply(capturedThiz, capturedArgs);
          } else {
            result = callback.handleEvent(args[0]);
          }
          span.end();
          return result;
        });
      };
      if (instrumentation.addPatchListener(ws, callback, patchedCallback)) {
        origAEL.apply(ws, [type, patchedCallback, options]);
      }
    };

    const origREL = ws.removeEventListener;
    ws.removeEventListener = function (type, callback, options) {
      if (type !== "message") {
        return origREL.call(ws, type, callback, options);
      }
      const patchedCallback = instrumentation.removePatchListener(ws, callback);
      if (patchedCallback) {
        return origREL.call(ws, type, patchedCallback, options);
      } else {
        return origREL.call(ws, type, callback, options);
      }
    };
  }
  endSpanExceptionally(span, err) {
    if (err.stack) {
      const stackFrames = ErrorStackParser.parse(err);
      span.setAttribute("error.structuredStack", jsonToString(stackFrames));
      span.setAttribute(
        "error.stack",
        limitLen(err.stack.toString(), STACK_LIMIT)
      );
      const exceptionStackFrame = getExceptionStackFrames(stackFrames);
      const eventData = {
        "exception.type": err.name,
        "exception.message": err.message,
        "exception.stacktrace": err.stack,
        "exception.stack_details": jsonToString(exceptionStackFrame),
      };
      span.addEvent("exception", eventData);
    }
    span.setAttribute("event.type", "error");
    span.setAttribute("error.message", err.message);
    span.setAttribute(
      "error.object",
      err.name
        ? err.name
        : err.constructor && err.constructor.name
          ? err.constructor.name
          : "Error"
    );
    span.setStatus({
      code: SpanStatusCode.ERROR,
      message: limitLen(err.message, MESSAGE_LIMIT),
    });
    span.end();
  }
}
exports.MiddlewareWebSocketInstrumentation = MiddlewareWebSocketInstrumentation;
