const {
  AlwaysOffSampler,
  AlwaysOnSampler,
} = require("@opentelemetry/sdk-trace-base");
const { getRumSessionId } = require("./session");

class SessionBasedSampler {
  constructor({
    ratio = 1,
    sampled = new AlwaysOnSampler(),
    notSampled = new AlwaysOffSampler(),
  } = {}) {
    this._ratio = this._normalize(ratio);
    this._upperBound = Math.floor(this._ratio * 0xffffffff);

    this._sampled = sampled;
    this._notSampled = notSampled;

    this._currentSession = null;
    this._currentSessionSampled = false;
  }

  shouldSample(context, traceId, spanName, spanKind, attributes, links) {
    const currentSession = getRumSessionId();
    if (!currentSession) {
      return this._notSampled.shouldSample(
        context,
        traceId,
        spanName,
        spanKind,
        attributes,
        links
      );
    }

    if (this._currentSession !== currentSession) {
      this._currentSessionSampled =
        this._accumulate(currentSession) < this._upperBound;
      this._currentSession = currentSession;
    }

    const sampler = this._currentSessionSampled
      ? this._sampled
      : this._notSampled;

    return sampler.shouldSample(
      context,
      traceId,
      spanName,
      spanKind,
      attributes,
      links
    );
  }

  toString() {
    return `SessionBased{ratio=${
      this._ratio
    }, sampled=${this._sampled.toString()}, notSampled=${this._notSampled.toString()}}`;
  }

  _normalize(ratio) {
    if (typeof ratio !== "number" || isNaN(ratio)) {
      return 0;
    }
    return ratio >= 1 ? 1 : ratio <= 0 ? 0 : ratio;
  }

  _accumulate(sessionId) {
    let accumulation = 0;
    for (let i = 0; i < sessionId.length / 8; i++) {
      const pos = i * 8;
      const part = parseInt(sessionId.slice(pos, pos + 8), 16);
      accumulation = (accumulation ^ part) >>> 0;
    }
    return accumulation;
  }
}

module.exports = {
  SessionBasedSampler,
};
