const { trace } = require("@opentelemetry/api");
const { InstrumentationBase } = require("@opentelemetry/instrumentation");

const TRACER_NAME = "@middleware.io/page-tracking-instrumentation";
const INSTRUMENTATION_NAME = "page-tracking-instrumentation";
const INSTRUMENTATION_VERSION = "1.0.0";

const EV_VISIBILITYCHANGE = "visibilitychange";
const EV_LOAD = "load";
const EV_SCROLL = "scroll";
const EV_POPSTATE = "popstate";
const EV_HASHCHANGE = "hashchange";
const EV_CHANGE = "change";
const EV_INPUT = "input";
const EV_SUBMIT = "submit";

class PageTrackingInstrumentation extends InstrumentationBase {
  constructor(config = {}) {
    super(INSTRUMENTATION_NAME, INSTRUMENTATION_VERSION, { enabled: false, ...config });
    this.enabled = false;
    this.initialPageLoadCaptured = false;
    this.lastPathName = "";
    this.provider = null;
    this.pageLeaveState = null;
    this.historyPatched = false;
    this._inputTrackingListener = null;
    this._submitTrackingListener = null;
    this._scrollTrackingListener = null;
    this.lastScrollCheckpoint = 0;
    this.scrollCheckpoints = (config.scrollCheckpoints || [25, 50, 75, 100]).slice().sort((a, b) => a - b);
    /** When false, form submit events are not recorded as spans. */
    this.trackSubmit = config.trackSubmit !== false;
  }

  init() {
    return [];
  }

  enable() {
    if (this.enabled) return;

    this.provider = trace.getTracerProvider();
    if (!this.provider) {
      console.warn(`[${INSTRUMENTATION_NAME}] No tracer provider found. Skipping init.`);
      return;
    }

    this.initPageLeaveTracking();
    this.patchHistory();
    this.initLocationChange();
    this.initInputTracking();
    this.initSubmitTracking();
    this.initScrollTracking();

    this.enabled = true;
  }

  disable() {
    this.enabled = false;
    if (typeof window !== "undefined") {
      if (this._inputTrackingListener) {
        window.removeEventListener(EV_CHANGE, this._inputTrackingListener);
        this._inputTrackingListener = null;
      }
      if (this._submitTrackingListener) {
        window.removeEventListener(EV_SUBMIT, this._submitTrackingListener);
        this._submitTrackingListener = null;
      }
      if (this._scrollTrackingListener) {
        window.removeEventListener(EV_SCROLL, this._scrollTrackingListener);
        this._scrollTrackingListener = null;
      }
    }
    this.lastScrollCheckpoint = 0;
  }

  isEnabled() {
    return this.enabled;
  }

  getTracer() {
    return this.provider.getTracer(TRACER_NAME);
  }

  patchHistory() {
    if (this.historyPatched || !window.history) return;
    this.historyPatched = true;

    const self = this;
    const origPush = window.history.pushState;
    const origReplace = window.history.replaceState;

    window.history.pushState = function (...args) {
      const result = origPush.apply(window.history, args);
      self.onNavigate("pushstate");
      return result;
    };

    window.history.replaceState = function (...args) {
      const result = origReplace.apply(window.history, args);
      self.onNavigate("replacestate");
      return result;
    };
  }

  onNavigate(type) {
    const currentUrl = this.getCurrentUrl();

    if (this.pageLeaveState && currentUrl !== this.pageLeaveState.previousTrackedUrl) {
      this.reportPageLeaveSpan(
        { type },
        this.pageLeaveState.previousTrackedUrl,
        this.pageLeaveState.previousScrollHeight
      );
      this.pageLeaveState.previousTrackedUrl = currentUrl;
      this.pageLeaveState.maxScrollViewDepth = this.getViewportHeight();
      this.pageLeaveState.previousScrollHeight = this.getScrollHeight();
      this.pageLeaveState.hasTrackedScrollSession = false;
    }

    this.captureLocationChange(type);
  }

  reportPageEvent(eventName, attributes = {}) {
    const span = this.getTracer().startSpan(eventName, {
      attributes: {
        "page.title": document.title,
        "root.url": window.location.pathname,
        "event.type": eventName,
        "page.href": window.location.href,
        ...attributes,
      },
    });
    span.end();
  }

  captureLocationChange(navigationType) {
    const newPathName = window.location.pathname;
    if (newPathName === this.lastPathName) return;

    Middleware.setAttributes({
      "page.title": document.title,
      "root.url": newPathName,
      "prev.root.url": this.lastPathName,
      "page.href": window.location.href,
      "referrer": document?.referrer || "direct",
      "referrer.domain": document?.referrer
        ? new URL(document.referrer).host
        : "direct",
    });

    window.viewCount += 1;

    // event.type stays "pageview" (from reportPageEvent). It used to be
    // overridden to "load", which collided with the documentLoad span: every
    // SPA route change then looked like a page load, and countIf(event.type =
    // 'pageview') — the view count — never matched anything. The initial
    // navigation is still distinguishable via navigation.type = "load".
    this.reportPageEvent("pageview", {
      "page.title": document.title,
      "root.url": newPathName,
      "page.href": window.location.href,
      "prev.root.url": this.lastPathName,
      "navigation.type": navigationType,
    });

    this.lastPathName = newPathName;
  }

  initLocationChange() {
    if (!this.initialPageLoadCaptured) {
      this.captureLocationChange("load");
      this.initialPageLoadCaptured = true;
    }

    window.addEventListener(EV_POPSTATE, () => {
      setTimeout(() => this.onNavigate("popstate"), 0);
    });

    window.addEventListener("pagehide", () => this.reportPageEvent("pagehide"), {
      passive: true,
    });
  }

  initInputTracking() {
    if (typeof window === "undefined") return;
    window.removeEventListener(EV_CHANGE, this._inputTrackingListener);

    this._inputTrackingListener = (ev) => {
      if (!this.enabled || !this.getTracer()) return;
      const target = ev && ev.target;
      if (!target || typeof target.tagName !== "string") return;

      const attributes = {
        "event.type": ev.type || EV_CHANGE,
        "input.tag": (target.tagName || "").toLowerCase(),
        "page.href": window.location.href,
      };
      if (target.type != null) attributes["input.type"] = String(target.type);
      if (target.name) attributes["input.name"] = String(target.name);
      if (target.id) attributes["input.id"] = String(target.id);

      const span = this.getTracer().startSpan("input_change", { attributes });
      span.end();
    };

    window.addEventListener(EV_CHANGE, this._inputTrackingListener);
  }

  initSubmitTracking() {
    if (typeof window === "undefined") return;
    window.removeEventListener(EV_SUBMIT, this._submitTrackingListener);

    if (!this.trackSubmit) {
      this._submitTrackingListener = null;
      return;
    }

    this._submitTrackingListener = (ev) => {
      if (!this.enabled || !this.getTracer() || !this.trackSubmit) return;
      const target = ev && ev.target;
      if (!target || typeof target.tagName !== "string") return;

      const tag = (target.tagName || "").toLowerCase();
      if (tag !== "form") return;

      const attributes = {
        "event.type": ev.type || EV_SUBMIT,
        "page.href": window.location.href,
      };
      if (target.method != null && target.method !== "") {
        attributes["form.method"] = String(target.method);
      }
      if (target.action != null && target.action !== "") {
        attributes["form.action"] = String(target.action);
      }
      if (target.name) attributes["form.name"] = String(target.name);
      if (target.id) attributes["form.id"] = String(target.id);

      const span = this.getTracer().startSpan("form_submit", { attributes });
      span.end();
    };

    window.addEventListener(EV_SUBMIT, this._submitTrackingListener);
  }

  initScrollTracking() {
    if (typeof window === "undefined" || typeof document === "undefined") return;
    window.removeEventListener(EV_SCROLL, this._scrollTrackingListener);
    this.lastScrollCheckpoint = 0;

    this._scrollTrackingListener = () => {
      if (!this.enabled || !this.getTracer()) return;

      const scrollTop = window.scrollY;
      let scrollHeight;
      let scrollPercentage;

      try {
        scrollHeight = document.body ? document.body.scrollHeight : 0;
        const maxScroll = scrollHeight - window.innerHeight;
        scrollPercentage = maxScroll > 0 ? Math.round((scrollTop / maxScroll) * 100) : 0;
      } catch (err) {
        return;
      }

      if (scrollPercentage <= this.lastScrollCheckpoint) return;

      let crossedCheckpoint = null;
      for (let i = 0; i < this.scrollCheckpoints.length; i++) {
        const checkpoint = this.scrollCheckpoints[i];
        if (scrollPercentage >= checkpoint && this.lastScrollCheckpoint < checkpoint) {
          crossedCheckpoint = checkpoint;
          this.lastScrollCheckpoint = checkpoint;
          break;
        }
      }

      if (crossedCheckpoint == null) return;

      const span = this.getTracer().startSpan("scroll", {
        attributes: {
          "event.type": "scroll",
          "scroll.scroll_top": scrollTop,
          "scroll.scroll_height": scrollHeight,
          "scroll.scroll_percentage": scrollPercentage,
          "scroll.checkpoint": crossedCheckpoint,
          "page.href": window.location.href,
        },
      });
      span.end();
    };

    window.addEventListener(EV_SCROLL, this._scrollTrackingListener);
  }

  getViewportHeight() {
    return Math.max(document.documentElement.clientHeight, window.innerHeight || 0);
  }

  getViewportWidth() {
    return Math.max(document.documentElement.clientWidth, window.innerWidth || 0);
  }

  getScrollHeight() {
    return document.body ? document.body.scrollHeight : 0;
  }

  getCurrentUrl() {
    return typeof window !== "undefined" && window.location
      ? window.location.href
      : "";
  }

  reportPageLeaveSpan(ev, currentUrl, currentScrollHeight) {
    const state = this.pageLeaveState;
    if (state.hasTrackedScrollSession) return;
    state.hasTrackedScrollSession = true;

    const vh = this.getViewportHeight();
    let scrollPct = 100;
    let foldPct = 100;

    if (currentScrollHeight > vh) {
      const maxScroll = Math.max(state.maxScrollViewDepth - vh, 0);
      const scrollRange = currentScrollHeight - vh;
      scrollPct = Math.round((maxScroll / scrollRange) * 100);
      foldPct = Math.round((vh / currentScrollHeight) * 100);
    }

    const span = this.getTracer().startSpan("pageleave", {
      attributes: {
        "event.type": (ev && ev.type) || EV_VISIBILITYCHANGE,
        "page.href": currentUrl || this.getCurrentUrl(),
        "pageleave.max_scroll_view_depth": state.maxScrollViewDepth,
        "pageleave.max_scroll_percentage": scrollPct,
        "pageleave.fold_line_percentage": foldPct,
        "pageleave.scroll_height": currentScrollHeight,
        "pageleave.viewport_height": vh,
        "pageleave.viewport_width": this.getViewportWidth(),
      },
    });
    span.end();
  }

  initPageLeaveTracking() {
    if (typeof document === "undefined" || typeof window === "undefined") return;

    this.pageLeaveState = {
      previousTrackedUrl: this.getCurrentUrl(),
      previousScrollHeight: this.getScrollHeight(),
      maxScrollViewDepth: this.getViewportHeight(),
      hasTrackedScrollSession: false,
    };

    window.addEventListener(EV_LOAD, () => {
      this.pageLeaveState.previousScrollHeight = this.getScrollHeight();
    });

    window.addEventListener(EV_SCROLL, () => {
      const scrollBottom = this.getViewportHeight() + window.scrollY;
      if (scrollBottom > this.pageLeaveState.maxScrollViewDepth) {
        this.pageLeaveState.maxScrollViewDepth = scrollBottom;
      }
      this.pageLeaveState.previousScrollHeight = this.getScrollHeight();
    });

    window.addEventListener(EV_HASHCHANGE, (ev) => this.onNavigate(ev.type));

    document.addEventListener(EV_VISIBILITYCHANGE, (ev) => {
      if (document.hidden) {
        this.reportPageLeaveSpan(
          ev,
          this.pageLeaveState.previousTrackedUrl,
          this.pageLeaveState.previousScrollHeight
        );
      }
    });
  }
}

module.exports = { PageTrackingInstrumentation };
