const { SessionBasedSampler } = require("./SessionBasedSampler");
const {
  AlwaysOffSampler,
  AlwaysOnSampler,
  ParentBasedSampler,
} = require("@opentelemetry/sdk-trace-base");
const { isBot } = require("./utils.js");

function track(newConfig = {}) {
  if (!newConfig.accountKey) {
    return "accountKey is required";
  } else if (!newConfig.target) {
    return "target is required";
  }

  // Block bot/crawler traffic by default so no RUM data (pageviews, spans,
  // errors, recordings, etc.) is captured for non-human agents. Consumers can
  // opt back in by passing `blockBotTraffic: false`.
  const blockBotTraffic = newConfig.blockBotTraffic !== false;
  if (blockBotTraffic && isBot()) {
    return "bot traffic blocked";
  }

  require("./config").init(newConfig);
}
module.exports.track = track;

function setAttributes(attributes = {}) {
  if (typeof attributes === "object" && Object.keys(attributes).length > 0) {
    require("./config").setAttributes(attributes);
  } else {
    console.error(
      "Invalid attributes format. Please provide a non-empty object."
    );
  }
}
module.exports.setAttributes = setAttributes;

function addAction(action, attributes = {}) {
  if (typeof action !== "string") {
    console.error("Invalid action format. Please provide a string.");
    return;
  }
  require("./config").addAction(action, attributes);
}
module.exports.addAction = addAction;

function getSessionId() {
  return require("./config").getSessionId();
}
module.exports.SessionBasedSampler = SessionBasedSampler;
module.exports.AlwaysOnSampler = AlwaysOnSampler;
module.exports.AlwaysOffSampler = AlwaysOffSampler;
module.exports.ParentBasedSampler = ParentBasedSampler;
function getTracer(name) {
  return require("./config").getTracer(name);
}
var Middleware = {};
Middleware.defaultAttributes = {};
Middleware.track = track;
Middleware.setAttributes = setAttributes;
Middleware.addAction = addAction;
Middleware.getSessionId = getSessionId;
Middleware.stopVideoRecording = require("./config").stopVideoRecording;
Middleware.resumeVideoRecording = require("./config").resumeVideoRecording;
Middleware.getTracer = getTracer;
Middleware.SessionBasedSampler = SessionBasedSampler;
Middleware.AlwaysOnSampler = AlwaysOnSampler;
Middleware.AlwaysOffSampler = AlwaysOffSampler;
Middleware.ParentBasedSampler = ParentBasedSampler;
Middleware.info = (msg = "") => {
  require("./config").info(msg);
};
Middleware.warn = (msg = "") => {
  require("./config").warn(msg);
};
Middleware.debug = (msg = "") => {
  require("./config").debug(msg);
};
Middleware.error = (msg = "") => {
  require("./config").error(msg);
};

Middleware.deinit = () => {
  require("./config").deinit();
};

if (typeof window !== "undefined") {
  window.Middleware = Middleware;
}
