'use strict';

const StackFrame = require('stackframe');

const FIREFOX_SAFARI_STACK_REGEXP = /(^|@)\S+:\d+/;
const CHROME_IE_STACK_REGEXP = /^\s*at .*(\S+:\d+|\(native\))/m;
const SAFARI_NATIVE_CODE_REGEXP = /^(eval@)?(\[native code])?$/;

const ErrorStackParser = {
  parse(error) {
    if (
      typeof error.stacktrace !== 'undefined' ||
      typeof error['opera#sourceloc'] !== 'undefined'
    ) {
      return this.parseOpera(error);
    } else if (error.stack && error.stack.match(CHROME_IE_STACK_REGEXP)) {
      return this.parseV8OrIE(error);
    } else if (error.stack) {
      return this.parseFFOrSafari(error);
    }
    throw new Error('Cannot parse given Error object');
  },

  extractLocation(urlLike) {
    if (urlLike.indexOf(':') === -1) {
      return [urlLike];
    }

    const regExp = /(.+?)(?::(\d+))?(?::(\d+))?$/;
    const parts = regExp.exec(urlLike.replace(/[()]/g, ''));
    return [parts[1], parts[2], parts[3]];
  },

  parseV8OrIE(error) {
    return error.stack
      .split('\n')
      .filter(line => CHROME_IE_STACK_REGEXP.test(line))
      .map(line => {
        if (line.indexOf('(eval ') > -1) {
          line = line
            .replace(/eval code/g, 'eval')
            .replace(/(\(eval at [^()]*)|(,.*$)/g, '');
        }

        let sanitizedLine = line
          .replace(/^\s+/, '')
          .replace(/\(eval code/g, '(')
          .replace(/^.*?\s+/, '');

        const location = sanitizedLine.match(/ (\(.+\)$)/);
        sanitizedLine = location
          ? sanitizedLine.replace(location[0], '')
          : sanitizedLine;

        const locationParts = this.extractLocation(
          location ? location[1] : sanitizedLine
        );

        const functionName = location && sanitizedLine || undefined;
        const fileName =
          ['eval', '<anonymous>'].includes(locationParts[0])
            ? undefined
            : locationParts[0];

        return new StackFrame({
          functionName,
          fileName,
          lineNumber: locationParts[1],
          columnNumber: locationParts[2],
          source: line
        });
      });
  },

  parseFFOrSafari(error) {
    return error.stack
      .split('\n')
      .filter(line => !SAFARI_NATIVE_CODE_REGEXP.test(line))
      .map(line => {
        if (line.indexOf(' > eval') > -1) {
          line = line.replace(
            / line (\d+)(?: > eval line \d+)* > eval:\d+:\d+/g,
            ':$1'
          );
        }

        if (line.indexOf('@') === -1 && line.indexOf(':') === -1) {
          return new StackFrame({ functionName: line });
        }

        const functionNameRegex = /((.*".+"[^@]*)?[^@]*)(?:@)/;
        const matches = line.match(functionNameRegex);
        const functionName = matches && matches[1] || undefined;

        const locationParts = this.extractLocation(
          line.replace(functionNameRegex, '')
        );

        return new StackFrame({
          functionName,
          fileName: locationParts[0],
          lineNumber: locationParts[1],
          columnNumber: locationParts[2],
          source: line
        });
      });
  },

  parseOpera(e) {
    if (
      !e.stacktrace ||
      (e.message.includes('\n') &&
        e.message.split('\n').length > e.stacktrace.split('\n').length)
    ) {
      return this.parseOpera9(e);
    } else if (!e.stack) {
      return this.parseOpera10(e);
    }
    return this.parseOpera11(e);
  },

  parseOpera9(e) {
    const lineRE = /Line (\d+).*script (?:in )?(\S+)/i;
    const lines = e.message.split('\n');
    const result = [];

    for (let i = 2; i < lines.length; i += 2) {
      const match = lineRE.exec(lines[i]);
      if (match) {
        result.push(
          new StackFrame({
            fileName: match[2],
            lineNumber: match[1],
            source: lines[i]
          })
        );
      }
    }

    return result;
  },

  parseOpera10(e) {
    const lineRE =
      /Line (\d+).*script (?:in )?(\S+)(?:: In function (\S+))?$/i;
    const lines = e.stacktrace.split('\n');
    const result = [];

    for (let i = 0; i < lines.length; i += 2) {
      const match = lineRE.exec(lines[i]);
      if (match) {
        result.push(
          new StackFrame({
            functionName: match[3],
            fileName: match[2],
            lineNumber: match[1],
            source: lines[i]
          })
        );
      }
    }

    return result;
  },

  parseOpera11(error) {
    return error.stack
      .split('\n')
      .filter(
        line =>
          FIREFOX_SAFARI_STACK_REGEXP.test(line) &&
          !line.startsWith('Error created at')
      )
      .map(line => {
        const tokens = line.split('@');
        const locationParts = this.extractLocation(tokens.pop());
        const functionCall = tokens.shift() || '';

        const functionName = functionCall
          .replace(/<anonymous function(: (\w+))?>/, '$2')
          .replace(/\([^)]*\)/g, '') || undefined;

        let args;
        const argsMatch = functionCall.match(/\(([^)]*)\)/);
        if (argsMatch && argsMatch[1] !== '[arguments not available]') {
          args = argsMatch[1].split(',');
        }

        return new StackFrame({
          functionName,
          args,
          fileName: locationParts[0],
          lineNumber: locationParts[1],
          columnNumber: locationParts[2],
          source: line
        });
      });
  }
};

module.exports = ErrorStackParser;
