const { SeverityNumber } = require("@opentelemetry/api-logs");
const stringifySafe = require("json-stringify-safe");
const { DEFAULT_USER_INTERACTION_ELEMENT_NAME_LIMIT } = require("./constants");
function getUserInteractionSpanName(
  eventType,
  element,
  userInteractionElementNameLimit
) {
  let id = "";
  let scanElement = element;
  let elementNameLimit =
    typeof userInteractionElementNameLimit === "number" &&
    userInteractionElementNameLimit > 0
      ? userInteractionElementNameLimit
      : DEFAULT_USER_INTERACTION_ELEMENT_NAME_LIMIT;
  while (scanElement && !id) {
    id =
      scanElement.getAttribute("aria-label") ||
      scanElement.getAttribute("name") ||
      scanElement.getAttribute("placeholder") ||
      scanElement.getAttribute("alt") ||
      scanElement.id ||
      scanElement.textContent ||
      scanElement.value ||
      "";
    id = String(id).trim();
    scanElement = scanElement.parentElement;
  }
  if (!id) {
    return eventType; // fallback if nothing useful
  }
  if (id.length > elementNameLimit) {
    id = id.slice(0, elementNameLimit);
  }
  return `${eventType} on '${id}'`;
}

function tryNumber(input) {
  if (typeof input === "number") {
    return input;
  }
  return input != null && Number.isFinite(+input) ? +input : undefined;
}

function getCollectionSourceUrl(sourceUrl) {
  const url = new URL(sourceUrl);
  url.pathname = url.pathname.replace(/\/v1\/(traces|metrics|logs)\/?$/, "");
  if (!url.pathname.endsWith("/")) {
    url.pathname += "/";
  }
  return url.href;
}

const EXTENSION_URL_PREFIXES = [
  "chrome-extension://",
  "moz-extension://", // Firefox
  "safari-extension://", // Safari
];

const IGNORE_SCAN_LIMIT = 8192;

const DEFAULT_STRINGIFY_MAX_LEN = 2048;
const DEFAULT_STRINGIFY_MAX_DEPTH = 4;

/**
 * Bounded replacement for jsonToString() on the console capture path.
 *
 * jsonToString() falls back to json-stringify-safe, which only breaks cycles
 * along the current ancestor path. Any node reachable by more than one path is
 * re-serialized once per path, so object graphs with back-references (Vue
 * reactive objects, hls.js/shaka player instances) blow up combinatorially and
 * hang the main thread. This walks with a global visited set, a depth cap and a
 * character budget, so cost is bounded no matter what the caller logged.
 */
function safeStringify(
  value,
  maxLen = DEFAULT_STRINGIFY_MAX_LEN,
  maxDepth = DEFAULT_STRINGIFY_MAX_DEPTH
) {
  if (maxLen <= 0) return "";
  if (typeof value === "string") return value.slice(0, maxLen);

  const seen = new WeakSet();
  const depths = new WeakMap();
  let budget = maxLen;

  try {
    const output = JSON.stringify(value, function (key, val) {
      if (budget <= 0) return undefined;
      if (val !== null && typeof val === "object") {
        // Global visited set, not ancestor-only: collapses shared subtrees
        // instead of re-walking them once per path.
        if (seen.has(val)) return "[Circular]";
        const depth = (depths.get(this) || 0) + 1;
        if (depth > maxDepth) return "[Object]";
        depths.set(val, depth);
        seen.add(val);
      }
      budget -= typeof val === "string" ? val.length : 8;
      return val;
    });
    return output == null ? "" : output.slice(0, maxLen);
  } catch (e) {
    try {
      return String(value).slice(0, maxLen);
    } catch (e2) {
      return "";
    }
  }
}

/**
 * Extension URLs only ever appear in strings and Error stacks, never buried
 * inside an object graph, so only textual arguments need scanning. Objects fall
 * back to a bounded safeStringify() rather than a full serialization.
 */
function collectScannableText(message) {
  if (typeof message === "string") return message;

  const args = Array.isArray(message) ? message : [message];
  let str = "";
  for (const arg of args) {
    if (str.length >= IGNORE_SCAN_LIMIT) break;
    if (typeof arg === "string") {
      str += arg + " ";
    } else if (arg instanceof Error) {
      str += (arg.stack || arg.message || "") + " ";
    } else if (arg !== null && typeof arg === "object") {
      str += safeStringify(arg, IGNORE_SCAN_LIMIT - str.length, 3) + " ";
    }
  }
  return str;
}

function shouldIgnoreMessage(message) {
  if (!message) return false;

  const str = collectScannableText(message);
  if (!str) return false;

  return EXTENSION_URL_PREFIXES.some((prefix) => str.includes(prefix));
}
function findCookieValue(cookieName) {
  const decodedCookie = decodeURIComponent(document.cookie);
  const cookies = decodedCookie.split(";");
  for (let i = 0; i < cookies.length; i++) {
    const c = cookies[i].trim();
    if (c.indexOf(cookieName + "=") === 0) {
      return c.substring((cookieName + "=").length, c.length);
    }
  }
  return undefined;
}

function isIframe() {
  try {
    return window.self !== window.top;
  } catch (e) {
    return true;
  }
}

function generateId(bits) {
  const xes = "x".repeat(bits / 4);
  return xes.replace(/x/g, function () {
    return ((Math.random() * 16) | 0).toString(16);
  });
}

function useful(s) {
  return (
    typeof s === "string" &&
    s.trim() !== "" &&
    !s.startsWith("[object") &&
    s !== "error"
  );
}

function stringifyValue(value) {
  if (value === undefined || value === null) {
    return "(undefined)";
  }

  return value.toString();
}

function jsonToString(json) {
  let output = "";
  let error = false;
  try {
    output = JSON.stringify(json);
  } catch (ex) {
    error = true;
    // ignore error
  }

  if (error) {
    try {
      output = stringifySafe(json);
    } catch (ex) {
      // ignore error
    }
  }

  return output;
}

function toOtelSeverityNumber(level) {
  switch (level) {
    case "DEBUG":
      return SeverityNumber.DEBUG;
    case "INFO":
      return SeverityNumber.INFO;
    case "WARN":
      return SeverityNumber.WARN;
    case "ERROR":
      return SeverityNumber.ERROR;
    case "CRITICAL":
      return SeverityNumber.FATAL;
    default:
      return SeverityNumber.UNSPECIFIED;
  }
}

function getBrowserName(userAgent = navigator.userAgent) {
  const browsers = [
    { name: "UCBrowser", regex: /(ucbrowser)/i },
    { name: "Edge", regex: /(edge|edga|edgios|edg)/i },
    { name: "GoogleBot", regex: /(googlebot)/i },
    { name: "Chromium", regex: /(chromium)/i },
    { name: "Firefox", regex: /(firefox|fxios)/i },
    { name: "Chrome", regex: /(chrome|crios)/i },
    { name: "Safari", regex: /(safari)/i },
    { name: "Opera", regex: /(opera|opr)/i },
  ];

  const browser = browsers.find(({ regex }) => regex.test(userAgent));

  return browser ? browser.name : "unknown";
}

function getBrowserVersion(userAgent = navigator.userAgent, browser) {
  const regexMap = {
    UCBrowser: /(ucbrowser)\/([\d\.]+)/i,
    Edge: /(edge|edga|edgios|edg)\/([\d\.]+)/i,
    GoogleBot: /(googlebot)\/([\d\.]+)/i,
    Chromium: /(chromium)\/([\d\.]+)/i,
    Firefox: /(firefox|fxios)\/([\d\.]+)/i,
    Chrome: /(chrome|crios)\/([\d\.]+)/i,
    Safari: /(safari)\/([\d\.]+)/i,
    Opera: /(opera|opr)\/([\d\.]+)/i,
    IE: /(trident)\/([\d\.]+)/i,
  };

  const version = userAgent.match(regexMap[browser]);

  if (browser === "IE") {
    return version ? `${parseFloat(version[2]) + 4.0}` : `7.0`;
  }

  return version ? version[2] : "0.0.0.0";
}

function getBrowserInfo(userAgent = navigator.userAgent) {
  const browser = getBrowserName(userAgent);
  const version = getBrowserVersion(userAgent, browser);
  return { browser, version };
}

const BOT_USER_AGENT_REGEX =
  /(googlebot|google-read-aloud|read-aloud|adsbot-google|mediapartners-google|apis-google|feedfetcher-google|bingbot|bingpreview|yandex(bot)?|baiduspider|duckduckbot|slurp|sogou|exabot|facebookexternalhit|facebot|ia_archiver|linkedinbot|twitterbot|slackbot|telegrambot|discordbot|whatsapp|embedly|quora link preview|pinterest(bot)?|redditbot|applebot|petalbot|semrushbot|ahrefsbot|mj12bot|dotbot|bytespider|amazonbot|gptbot|oai-searchbot|chatgpt-user|claudebot|anthropic-ai|perplexitybot|ccbot|dataforseobot|screaming frog|lighthouse|chrome-lighthouse|pagespeed|gtmetrix|pingdom|uptimerobot|statuscake|headlesschrome|headless|phantomjs|puppeteer|playwright|selenium|webdriver|crawler|spider|crawling|\bbot\b)/i;

function isBot(userAgent = typeof navigator !== "undefined" ? navigator.userAgent : "") {
  if (!userAgent || typeof userAgent !== "string") return false;
  return BOT_USER_AGENT_REGEX.test(userAgent);
}

function getExceptionStackFrames(stackFrames) {
  return stackFrames.map((stackFrame) => ({
    "exception.line": stackFrame.lineNumber,
    "exception.function_name": stackFrame.functionName,
    "exception.function_body": stackFrame.source,
    "exception.column_number": stackFrame.columnNumber,
    "exception.file": stackFrame.fileName,
  }));
}

function normalizeSet(inputSet, normalizeFn) {
  const normalizedSet = new Set();

  for (const value of inputSet) {
    normalizedSet.add(normalizeFn(value));
  }

  return normalizedSet;
}

function normalizeContentType(type) {
  if (!type) return "";
  const [baseType] = type.split(";", 1);
  return baseType.trim().toLowerCase();
}

function toLowerCase(value) {
  return typeof value === "string" ? value.toLowerCase() : value;
}

function isObject(value) {
  var type = typeof value;
  return value != null && (type == "object" || type == "function");
}

function isArray(value) {
  return Array.isArray(value);
}

function isPlainObject(value) {
  if (!isObject(value)) return false;

  const proto = Object.getPrototypeOf(value);
  return proto === null || proto === Object.prototype;
}

function isString(value) {
  return typeof value === "string" || value instanceof String;
}

const EVENT_HANDLER_ATTRIBUTES = [
  "onclick",
  "onmousedown",
  "onmouseup",
  "onpointerdown",
  "onpointerup",
  "ontouchend",
  "ontouchstart",
];

const INTERACTIVE_ARIA_ROLES = {
  button: true,
  checkbox: true,
  combobox: true,
  grid: true,
  link: true,
  listbox: true,
  menu: true,
  menubar: true,
  menuitem: true,
  menuitemcheckbox: true,
  menuitemradio: true,
  navigation: true,
  option: true,
  radio: true,
  radiogroup: true,
  searchbox: true,
  slider: true,
  spinbutton: true,
  switch: true,
  tab: true,
  tablist: true,
  textbox: true,
  tree: true,
  treegrid: true,
  treeitem: true,
};

const ALWAYS_NON_INTERACTIVE_TAGS = {
  base: true,
  head: true,
  html: true,
  link: true,
  meta: true,
  script: true,
  style: true,
  title: true,
  br: true,
  hr: true,
  wbr: true,
  noscript: true,
  picture: true,
  source: true,
  template: true,
  track: true,
};

const TEXT_CONTAINER_TAGS = {
  article: true,
  div: true,
  h1: true,
  h2: true,
  h3: true,
  h4: true,
  h5: true,
  h6: true,
  p: true,
  section: true,
  span: true,
};

const MAX_DEPTH = 5;

function hasInlineEventHandlers(element) {
  for (let i = 0; i < EVENT_HANDLER_ATTRIBUTES.length; i++) {
    if (element.hasAttribute(EVENT_HANDLER_ATTRIBUTES[i])) {
      return true;
    }
  }
  return false;
}

function hasInteractiveAriaRole(element) {
  const role = element.getAttribute("role");
  if (!role) return false;
  const primaryRole = role.trim().split(/\s+/)[0].toLowerCase();
  return INTERACTIVE_ARIA_ROLES[primaryRole];
}

function hasAnyInteractivityIndicators(element) {
  const tagName = element.tagName && element.tagName.toLowerCase();

  if (
    tagName === "button" ||
    tagName === "input" ||
    tagName === "select" ||
    tagName === "textarea" ||
    tagName === "details" ||
    tagName === "dialog"
  ) {
    return true;
  }

  if (element.isContentEditable) {
    return true;
  }

  if (
    element.onclick ||
    element.onmousedown ||
    element.onmouseup ||
    element.ontouchstart ||
    element.ontouchend
  ) {
    return true;
  }

  if (hasInlineEventHandlers(element)) {
    return true;
  }

  if (hasInteractiveAriaRole(element)) {
    return true;
  }

  if (tagName === "a" && element.hasAttribute("href")) {
    return true;
  }

  if (element.hasAttribute("tabindex")) {
    return true;
  }

  return false;
}

function isDefinitelyNonInteractive(element) {
  const doc =
    typeof globalThis !== "undefined" && globalThis.document
      ? globalThis.document
      : typeof window !== "undefined" && window.document
        ? window.document
        : null;
  if (!element || !element.tagName) {
    return true;
  }

  const tagName = element.tagName.toLowerCase();

  if (ALWAYS_NON_INTERACTIVE_TAGS[tagName]) {
    return true;
  }

  if (hasAnyInteractivityIndicators(element)) {
    return false;
  }

  let parent = element.parentElement;
  let depth = 0;

  while (parent && depth < MAX_DEPTH) {
    if (hasAnyInteractivityIndicators(parent)) {
      return false;
    }

    if (doc && parent.getRootNode && parent.getRootNode() !== doc) {
      const root = parent.getRootNode();
      if (root.host && hasAnyInteractivityIndicators(root.host)) {
        return false;
      }
    }

    parent = parent.parentElement;
    depth++;
  }

  if (TEXT_CONTAINER_TAGS[tagName]) {
    return true;
  }

  return false;
}

function getClickEventComposedPath(event) {
  if ("composedPath" in event) {
    return event.composedPath();
  }
  return [];
}

function getClickEventTargetElement(event) {
  const path = getClickEventComposedPath(event);

  if (path && path.length > 0) {
    return path[0];
  }

  return event.target || event.srcElement;
}

// <link> and SVG <image>/<use> load from href, not src; SVG's href is an SVGAnimatedString.
function getElementUrl(element) {
  if (!element) return undefined;
  const url = element.src || element.href;
  if (typeof url === "string") return url || undefined;
  return (url && url.baseVal) || undefined;
}

module.exports = {
  getCollectionSourceUrl,
  getUserInteractionSpanName,
  getClickEventComposedPath,
  getClickEventTargetElement,
  getElementUrl,
  isDefinitelyNonInteractive,
  tryNumber,
  shouldIgnoreMessage,
  findCookieValue,
  isIframe,
  generateId,
  useful,
  stringifyValue,
  jsonToString,
  toOtelSeverityNumber,
  getBrowserName,
  getBrowserVersion,
  getBrowserInfo,
  isBot,
  getExceptionStackFrames,
  normalizeSet,
  normalizeContentType,
  isArray,
  toLowerCase,
  isObject,
  isPlainObject,
  isString,
  safeStringify,
  collectScannableText,
};
