const { findCookieValue, isIframe, generateId } = require("./utils.js");

/*
    The basic idea is to let the browser expire cookies for us "naturally" once
    IntactivityTimeout is reached.  Activity (including any page load)
    extends the session.  The true startTime of the session is set in the cookie value
    and if an extension would ever exceed MaxAge it doesn't happen.
    We use a background periodic timer to check for expired cookies and initialize new ones.
    Session state is stored in the cookie as uriencoded json and is of the form
    {
        id: 'sessionIdAsHex',
        startTime: startTimeAsNewDate_getTime
    }
    Future work can add more fields though note that the fact that the value doesn't change
    once created makes this very robust when used in multiple tabs/windows - tabs don't compete/
    race to do anything but set the max-age.

    Finally, if SessionId exists, use its session ID exclusively and don't bother
    with setting cookies, checking for inactivity, etc.
*/

const MAX_SESSION_AGE = 4 * 60 * 60 * 1000;
const INACTIVITY_TIMEOUT_SECONDS = 15 * 60;
const PeriodicCheckSeconds = 60;
const COOKIE_NAME = "_mwRumSessionId_0_3";

let rumSessionId;
let startTime;
let recentActivity = false;
let cookieDomain;

const isTabVisible = () => document.visibilityState === "visible";

const markActivity = () => {
  if (isTabVisible()) {
    recentActivity = true;
  }
};

exports.markActivity = markActivity;

const pastMaxAge = (startTime) => {
  const now = Date.now();
  return startTime > now || now > startTime + MAX_SESSION_AGE;
};

const parseCookieToSessionState = () => {
  const rawValue = findCookieValue(COOKIE_NAME);
  if (!rawValue) {
    return undefined;
  }
  const decoded = decodeURIComponent(rawValue);
  if (!decoded) {
    return undefined;
  }
  let ss = undefined;
  try {
    ss = JSON.parse(decoded);
  } catch (error) {
    return undefined;
  }
  // should exist and be an object
  if (!ss || typeof ss !== "object") {
    return undefined;
  }
  // id validity
  if (!ss.id || typeof ss.id !== "string") {
    return undefined;
  }
  // startTime validity
  if (
    !ss.startTime ||
    typeof ss.startTime !== "number" ||
    pastMaxAge(ss.startTime)
  ) {
    return undefined;
  }
  return ss;
};

const newSessionState = () => {
  return {
    id: generateId(128),
    startTime: Date.now(),
  };
};

const renewCookieTimeout = (sessionState) => {
  if (pastMaxAge(sessionState.startTime)) {
    // safety valve
    return;
  }
  const cookieValue = encodeURIComponent(JSON.stringify(sessionState));
  const domain = cookieDomain ? `domain=${cookieDomain};` : "";
  let cookie =
    COOKIE_NAME +
    "=" +
    cookieValue +
    "; path=/;" +
    domain +
    "max-age=" +
    INACTIVITY_TIMEOUT_SECONDS;

  if (isIframe()) {
    cookie += ";SameSite=None; Secure";
  } else if (window.location.origin.startsWith("https")) {
    cookie += ";SameSite=Strict; Secure";
  } else {
    cookie += ";SameSite=Strict";
  }
  document.cookie = cookie;
};

// This is called periodically and has two purposes:
// 1) Check if the cookie has been expired by the browser; if so, create a new one
// 2) If activity has occured since the last periodic invocation, renew the cookie timeout
// (Only exported for testing purposes.)
const updateSessionStatus = (reinit) => {
  let sessionState = parseCookieToSessionState();
  if (!sessionState) {
    if (isTabVisible()) {
      sessionState = newSessionState();
      recentActivity = true; // force write of new cookie
      reinit();
    } else {
      recentActivity = false;
    }
  }
  rumSessionId = sessionState?.id;
  startTime = sessionState?.startTime;
  if (recentActivity) {
    renewCookieTimeout(sessionState);
  }
  recentActivity = false;
};

const hasNativeSessionId = () => {
  return (
    typeof window !== "undefined" &&
    window["MiddlewareNative"] &&
    window["MiddlewareNative"].getNativeSessionId
  );
};

const initSessionTracking = (reinit, sessionId, domain) => {
  //DONOT check for watching inactivity timeout if native session is created.
  if (hasNativeSessionId()) {
    return;
  }

  if (domain) {
    cookieDomain = domain;
  }
  rumSessionId = sessionId;
  recentActivity = true; // document loaded implies activity

  updateSessionStatus(reinit);
  const intervalHandle = setInterval(
    () => updateSessionStatus(reinit),
    PeriodicCheckSeconds * 1000
  );

  [
    "click",
    "scroll",
    "mousedown",
    "keydown",
    "touchend",
    "visibilitychange",
  ].forEach((type) =>
    document.addEventListener(type, markActivity, {
      capture: true,
      passive: true,
    })
  );

  return {
    deinit: () => {
      clearInterval(intervalHandle);
      rumSessionId = undefined;
    },
  };
};

exports.initSessionTracking = initSessionTracking;

const getRumSessionId = () => {
  if (hasNativeSessionId()) {
    return window["MiddlewareNative"].getNativeSessionId();
  }
  return rumSessionId;
};

exports.getRumSessionId = getRumSessionId;

const getSessionStartTime = () => {
  return startTime;
};

exports.getSessionStartTime = getSessionStartTime;
