/**
 * Resource Timing phase markers are only exposed when the response passes the
 * Timing-Allow-Origin check. When it fails, the browser reports 0 for every
 * marker (dns/connect/tls/request/response) and for all three size fields,
 * leaving only startTime, fetchStart and responseEnd populated.
 *
 * Subtracting those zeroes turns a timestamp into a bogus duration:
 * `responseEnd - responseStart` becomes `responseEnd`, i.e. how far into the
 * page load the resource finished, reported as if it were download time. The
 * guards below omit a phase instead of emitting that. `resource.timing_visible`
 * is emitted (false) whenever the phases had to be dropped, so dashboards and
 * alerts can exclude resources whose timings the browser never exposed.
 */

/** A marker or size the browser actually populated — 0 means "not available". */
const isPositive = (value) => typeof value === "number" && value > 0;

/** Emits `end - start`, but only when both markers are actually populated. */
function setPhase(span, name, start, end) {
  if (isPositive(start) && typeof end === "number" && end >= start) {
    span.setAttribute(name, end - start);
  }
}

/**
 * Sets the resource.* size and timing attributes shared by the document-load,
 * fetch and XHR instrumentations.
 *
 * @param span span to annotate
 * @param resource a PerformanceResourceTiming entry
 */
function setResourceTimingAttributes(span, resource) {
  if (!span || !resource) {
    return;
  }

  span.setAttribute("resource.size", resource.decodedBodySize);
  span.setAttribute("resource.transfer_size", resource.transferSize);
  span.setAttribute("resource.nextHopProtocol", resource.nextHopProtocol);

  // transferSize 0 with a decoded body means the browser served it from cache.
  // Both are zeroed when timings are hidden, so this only detects a cache hit
  // on resources whose sizes the browser exposed.
  if (resource.transferSize === 0 && isPositive(resource.decodedBodySize)) {
    span.setAttribute("resource.cache_hit", true);
  }

  // workerStart is non-zero only when a service worker handled the request.
  // Those responses reach the page with every phase marker, both sizes and
  // nextHopProtocol blanked out, which is indistinguishable from a hidden
  // cross-origin timing unless the worker is called out explicitly. The
  // browser records fetchStart once the worker is running, so
  // fetchStart - workerStart is how long the request waited for it to boot.
  if (isPositive(resource.workerStart)) {
    span.setAttribute("resource.service_worker", true);
    setPhase(
      span,
      "resource.worker_startup.duration",
      resource.workerStart,
      resource.fetchStart
    );
  }

  const timingVisible =
    isPositive(resource.requestStart) && isPositive(resource.responseStart);

  if (!timingVisible) {
    span.setAttribute("resource.timing_visible", false);
    // fetchStart -> responseEnd is the only span of time the browser still
    // exposes, so it is the only total that can be reported honestly here.
    setPhase(
      span,
      "resource.duration",
      resource.startTime,
      resource.responseEnd
    );
    return;
  }

  setPhase(
    span,
    "resource.duration",
    resource.requestStart,
    resource.responseEnd
  );
  setPhase(
    span,
    "resource.connect.duration",
    resource.connectStart,
    resource.connectEnd
  );
  setPhase(
    span,
    "resource.dns.duration",
    resource.domainLookupStart,
    resource.domainLookupEnd
  );
  setPhase(
    span,
    "resource.first_byte.duration",
    resource.requestStart,
    resource.responseStart
  );
  setPhase(
    span,
    "resource.download.duration",
    resource.responseStart,
    resource.responseEnd
  );

  // secureConnectionStart is 0 when no TLS handshake happened on this fetch —
  // a reused connection, a cache hit or plain http — so the handshake really
  // did take no time, rather than the value being unavailable.
  if (isPositive(resource.secureConnectionStart)) {
    setPhase(
      span,
      "resource.ssl.duration",
      resource.secureConnectionStart,
      resource.connectEnd
    );
  } else {
    span.setAttribute("resource.ssl.duration", 0);
  }

  // Same reasoning: no redirect at all is a true zero, not a missing value.
  if (isPositive(resource.redirectStart)) {
    setPhase(
      span,
      "resource.redirect.duration",
      resource.redirectStart,
      resource.redirectEnd
    );
  } else {
    span.setAttribute("resource.redirect.duration", 0);
  }
}

/**
 * Sets the status code of a resource the page loaded (script, stylesheet,
 * image, font...). Fetch and XHR spans get `http.response.status_code` from
 * their own instrumentation; document-load resource spans have only this entry
 * to read it from.
 *
 * responseStatus is 0 when the browser withholds it, which is a cross-origin
 * response without Timing-Allow-Origin or a browser that does not implement the
 * field. That 0 stays on `resource.status_code` as before, but is kept off the
 * HTTP key, where it would read as a real status.
 *
 * @param span span to annotate
 * @param resource a PerformanceResourceTiming entry
 */
function setResourceStatusAttributes(span, resource) {
  if (!span || !resource) {
    return;
  }

  span.setAttribute("resource.status_code", resource.responseStatus);
  if (isPositive(resource.responseStatus)) {
    span.setAttribute("http.response.status_code", resource.responseStatus);
  }
}

module.exports = {
  setResourceTimingAttributes,
  setResourceStatusAttributes,
};
