const sdkMetrics = require("./sdk-metrics");

class GzipOTLPTraceExporter {
  constructor(config) {
    this._url = config.url;
    this._headers = config.headers;

    // Read _mw_no_gzip from current page URL
    const urlParams = new URLSearchParams(window.location.search);
    const forceNoGzip = urlParams.get("_mw_no_gzip") === "1";

    // Fallback if param set OR browser doesn't support CompressionStream
    this._supportsGzip =
      !forceNoGzip && typeof CompressionStream !== "undefined";

    if (!this._supportsGzip) {
      const {
        OTLPTraceExporter,
      } = require("@opentelemetry/exporter-trace-otlp-http");
      this._fallbackExporter = new OTLPTraceExporter({
        url: this._url,
        headers: this._headers,
      });
    }
  }

  _wrapCallback(spans, bytes, resultCallback) {
    return (result) => {
      const status = result && result.code === 0 ? "ok" : "error";
      sdkMetrics.recordExport({
        signal: "traces",
        status,
        bytes: typeof bytes === "number" ? bytes : undefined,
        count: spans ? spans.length : undefined,
      });
      resultCallback(result);
    };
  }

  export(spans, resultCallback) {
    if (!this._supportsGzip) {
      return this._fallbackExporter.export(
        spans,
        this._wrapCallback(spans, undefined, resultCallback)
      );
    }

    // OTLPTraceExporter.convert() was removed in the 2.x line; the serializer
    // is now the public way to get the OTLP JSON payload, and it hands back the
    // encoded bytes directly.
    const { JsonTraceSerializer } = require("@opentelemetry/otlp-transformer");
    const serialized = JsonTraceSerializer.serializeRequest(spans);

    this._sendGzip(serialized, spans, resultCallback);
  }

  _sendGzip(body, spans, resultCallback) {
    const wrappedCallback = this._wrapCallback(
      spans,
      body.byteLength,
      resultCallback
    );
    const stream = new CompressionStream("gzip");
    const writer = stream.writable.getWriter();
    writer.write(body);
    writer.close();

    new Response(stream.readable)
      .arrayBuffer()
      .then((compressed) => {
        fetch(this._url, {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            "Content-Encoding": "gzip",
            Authorization: this._headers?.Authorization,
          },
          body: compressed,
        })
          .then((res) => {
            if (res.ok) wrappedCallback({ code: 0 });
            else wrappedCallback({ code: 1 });
          })
          .catch(() => wrappedCallback({ code: 1 }));
      })
      .catch(() => {
        // Runtime compression failure — fallback
        this._fallbackExporter =
          new (require("@opentelemetry/exporter-trace-otlp-http").OTLPTraceExporter)(
            {
              url: this._url,
              headers: this._headers,
            }
          );
        this._fallbackExporter.export(spans, wrappedCallback);
      });
  }

  shutdown() {
    if (this._fallbackExporter) {
      return this._fallbackExporter.shutdown();
    }
    return Promise.resolve();
  }
}
exports.GzipOTLPTraceExporter = GzipOTLPTraceExporter;
