const { convertToAnyValue } = require("./sessionRecordingUtils");
const sdkMetrics = require("./sdk-metrics");

// Browsers cap the bytes in flight across all keepalive requests at 64KB; a
// request over the cap is rejected outright. The logs exporter shares the cap.
const KEEPALIVE_MAX_BYTES = 60 * 1024;

class RRWebExporter {
  provider = undefined;
  /**
   * @param resource the SDK resource whose attributes are stamped on every
   *   exported batch. It is passed in rather than read back off the provider
   *   because SDK 2.x removed the provider's public `resource` accessor, which
   *   used to make `provider.resource.attributes` throw here and take session
   *   recording down with it. This mirrors how LogsExporter is wired.
   */
  constructor(config, provider, resource) {
    this.config = config;
    this.provider = provider;
    this.resource = resource ?? provider?.resource;
  }

  constructMetricData = (events) => {
    if (this.provider === undefined) {
      return;
    }

    const attributes = convertToAnyValue(this.resource?.attributes || {})
      ?.kvlistValue?.values;
    const resource = {
      attributes,
      droppedAttributesCount: 0,
    };

    const scopeMetric = {};
    scopeMetric["scope"] = {};
    const metrics = [];
    events.forEach((event) => {
      const metric = {
        name: "rum_event",
        gauge: {
          dataPoints: [
            {
              attributes: [
                {
                  key: "type",
                  value: {
                    stringValue: String(event.type),
                  },
                },
                {
                  key: "timestamp",
                  value: {
                    stringValue: String(event.timestamp),
                  },
                },
                {
                  key: "data",
                  value: {
                    stringValue: JSON.stringify(event.data),
                  },
                },
              ],
              timeUnixNano: String(event.timestamp * 1e6),
              asDouble: 0,
            },
          ],
        },
      };
      metrics.push(metric);
    });
    scopeMetric["metrics"] = metrics;
    const data = {
      resourceMetrics: [{ resource, scopeMetrics: [scopeMetric] }],
    };
    const c = JSON.stringify(data);
    return c;
  };

  // `keepalive`: the page is being hidden or unloaded, so send now and ask the
  // browser to finish the request after the document is gone.
  export(events, { keepalive = false } = {}) {
    if (!events || events.length === 0) return;

    const data = this.constructMetricData(events);
    if (!data) return;

    const eventCount = events.length;
    const bytes = data.length;

    const url = `${this.config.target}/v1/metrics`;
    const plainHeaders = {
      "Content-Type": "application/json",
      Authorization: this.config.accountKey,
    };

    const recordResult = (status) => {
      sdkMetrics.recordExport({
        signal: "recording",
        status,
        bytes,
        count: eventCount,
      });
    };

    const handleResponse = (response) => {
      if (!response.ok) {
        recordResult("error");
        if (response.status === 500) {
          response
            .text()
            .then((text) => {
              const trimmed = (text || "").trim();
              if (!trimmed) return;
              try {
                const jsonError = JSON.parse(trimmed);
                if (jsonError?.message) {
                  console.error(
                    "Middleware:",
                    jsonError.message,
                    `. Please contact support team.`
                  );
                }
              } catch {
                // empty or non-JSON body
              }
            })
            .catch(() => {});
        }
        return;
      }
      recordResult("ok");
    };

    if (keepalive) {
      // Gzip is async and would not complete before the page is gone. A batch
      // over the keepalive cap goes as a normal request: usually it still gets
      // out during the navigation, and a rejected keepalive cannot be retried
      // without risking a duplicate send.
      const body = new TextEncoder().encode(data);
      fetch(url, {
        method: "POST",
        headers: plainHeaders,
        body,
        keepalive: body.length <= KEEPALIVE_MAX_BYTES,
      })
        .then(handleResponse)
        .catch(() => {
          recordResult("error");
        });
      return;
    }

    const urlParams = new URLSearchParams(window.location.search);
    const forceNoGzip = urlParams.get("_mw_no_gzip") === "1";
    const supportsGzip =
      !forceNoGzip && typeof CompressionStream !== "undefined";

    if (!supportsGzip) {
      fetch(url, { method: "POST", headers: plainHeaders, body: data })
        .then(handleResponse)
        .catch(() => {
          recordResult("error");
        });
      return;
    }

    const stream = new CompressionStream("gzip");
    const writer = stream.writable.getWriter();
    writer.write(new TextEncoder().encode(data));
    writer.close();

    new Response(stream.readable)
      .arrayBuffer()
      .then((compressed) => {
        fetch(url, {
          method: "POST",
          headers: { ...plainHeaders, "Content-Encoding": "gzip" },
          body: compressed,
        })
          .then(handleResponse)
          .catch(() => {
            recordResult("error");
          });
      })
      .catch(() => {
        // CompressionStream failed at runtime — fallback to plain JSON
        fetch(url, { method: "POST", headers: plainHeaders, body: data })
          .then(handleResponse)
          .catch(() => {
            recordResult("error");
          });
      });
  }
}

module.exports = RRWebExporter;
