const { trace, context } = require("@opentelemetry/api");
// The attribution build is the same collectors plus an `attribution` object on
// every metric, explaining *why* the number is what it is: which element was
// the LCP, which interaction caused the worst INP and where its time went,
// which node shifted. Without it a poor score tells you nothing actionable.
const {
  onCLS,
  onLCP,
  onINP,
  onFCP,
  onTTFB,
} = require("web-vitals/attribution");
const { InstrumentationBase } = require("@opentelemetry/instrumentation");
const { jsonToString } = require("./utils.js");

/** `largestShiftTarget` -> `largest_shift_target` */
function toSnakeCase(key) {
  return key
    .replace(/([a-z0-9])([A-Z])/g, "$1_$2")
    .replace(/([A-Z]+)([A-Z][a-z])/g, "$1_$2")
    .toLowerCase();
}

/**
 * Flattens the scalar fields of an attribution object onto the span.
 *
 * Copying the keys web-vitals itself uses, rather than a hand-written mapping,
 * keeps the attribute names honest as the library adds fields. Object-valued
 * fields are skipped on purpose: they are raw PerformanceEntry objects
 * (`lcpEntry`, `navigationEntry`, `longAnimationFrameEntries`, …) that are
 * large, deeply nested and already summarised by the scalars beside them.
 */
function setAttributionAttributes(span, attribution, prefix) {
  if (!attribution || typeof attribution !== "object") {
    return;
  }
  for (const [key, value] of Object.entries(attribution)) {
    if (value === undefined || value === null || typeof value === "object") {
      continue;
    }
    span.setAttribute(`${prefix}.${toSnakeCase(key)}`, value);
  }
}

/**
 * INP's `longestScript` is the single most useful thing in the whole
 * attribution payload — it names the script that blocked the interaction — so
 * its scalars are pulled out rather than dropped with the other objects.
 */
function setLongestScriptAttributes(span, longestScript, prefix) {
  if (!longestScript || typeof longestScript !== "object") {
    return;
  }
  setAttributionAttributes(span, longestScript, `${prefix}.longest_script`);
  const entry = longestScript.entry;
  if (!entry) {
    return;
  }
  setAttributionAttributes(
    span,
    {
      sourceUrl: entry.sourceURL,
      sourceFunctionName: entry.sourceFunctionName,
      sourceCharPosition: entry.sourceCharPosition,
      invoker: entry.invoker,
      invokerType: entry.invokerType,
      duration: entry.duration,
      startTime: entry.startTime,
    },
    `${prefix}.longest_script`
  );
}

class WebVitalsInstrumentation extends InstrumentationBase {
  constructor(config = {}) {
    super("webvitals-instrumentation", "1.0.0", config);
    this._listeners = [];
  }

  // Required since @opentelemetry/instrumentation 0.200: the base constructor
  // calls init() unconditionally. This instrumentation patches nothing at
  // module load, so it has no definitions to return.
  init() {}

  report(ctx, name, metric) {
    const webVitalsSpan = trace
      .getTracer("webvitals")
      .startSpan(name, undefined, ctx);

    webVitalsSpan.setAttributes({
      "web_vital.name": name,
      "web_vital.id": metric.id,
      "web_vital.navigationType": metric.navigationType,
      "web_vital.delta": metric.delta,
      "web_vital.rating": metric.rating,
      "web_vital.value": metric.value,
      "web_vital.entries": jsonToString(metric.entries),
    });

    const attribution = metric.attribution;
    setAttributionAttributes(
      webVitalsSpan,
      attribution,
      "web_vital.attribution"
    );
    if (attribution) {
      setLongestScriptAttributes(
        webVitalsSpan,
        attribution.longestScript,
        "web_vital.attribution"
      );
    }

    webVitalsSpan.end();
  }

  enable() {
    if (this._enabled) return;
    this._enabled = true;

    const tracer = trace.getTracer("webvitals");
    const parentSpan = tracer.startSpan("webvitals");
    const ctx = trace.setSpan(context.active(), parentSpan);
    parentSpan.end();

    // onFID was removed in web-vitals 5: First Input Delay was retired in
    // favour of INP, which measures the whole interaction rather than just its
    // start. Nothing replaces the `first-input-delay` span.
    onCLS((metric) => this.report(ctx, "layout-shift", metric));
    onLCP((metric) => this.report(ctx, "largest-contentful-paint", metric));
    onINP((metric) => this.report(ctx, "interaction-next-paint", metric));
    onFCP((metric) => this.report(ctx, "first-contentful-paint", metric));
    onTTFB((metric) => this.report(ctx, "ttfb", metric));
  }

  disable() {
    if (!this._enabled) return;
    this._enabled = false;
  }
}

module.exports = {
  WebVitalsInstrumentation,
  toSnakeCase,
  setAttributionAttributes,
};
