const { MASK_VALUE } = require("../sessionRecordingUtils.js");

const ResourceType = {
  DOCUMENT: "document",
  XHR: "xhr",
  BEACON: "beacon",
  FETCH: "fetch",
  CSS: "css",
  JS: "js",
  IMAGE: "image",
  FONT: "font",
  MEDIA: "media",
  OTHER: "other",
};

const RequestType = {
  FETCH: ResourceType.FETCH,
  XHR: ResourceType.XHR,
};

const FAKE_INITIAL_DOCUMENT = "initial_document";
function includes(candidate, search) {
  return candidate.indexOf(search) !== -1;
}
const RESOURCE_TYPES = [
  [
    ResourceType.DOCUMENT,
    (initiatorType) => FAKE_INITIAL_DOCUMENT === initiatorType,
  ],
  [ResourceType.XHR, (initiatorType) => "xmlhttprequest" === initiatorType],
  [ResourceType.FETCH, (initiatorType) => "fetch" === initiatorType],
  [ResourceType.BEACON, (initiatorType) => "beacon" === initiatorType],
  [ResourceType.CSS, (_, path) => /\.css$/i.test(path)],
  [ResourceType.JS, (_, path) => /\.js$/i.test(path)],
  [
    ResourceType.IMAGE,
    (initiatorType, path) =>
      includes(["image", "img", "icon"], initiatorType) ||
      /\.(gif|jpg|jpeg|tiff|png|svg|ico)$/i.exec(path) !== null,
  ],
  [
    ResourceType.FONT,
    (_, path) => /\.(woff|eot|woff2|ttf)$/i.exec(path) !== null,
  ],
  [
    ResourceType.MEDIA,
    (initiatorType, path) =>
      includes(["audio", "video"], initiatorType) ||
      /\.(mp3|mp4)$/i.exec(path) !== null,
  ],
];
const getResponseHeaders = (responseHeaders) => {
  const arr = responseHeaders.trim().split(/[\r\n]+/);

  // Create a map of header names to values
  const headerMap = {};
  arr.forEach((line) => {
    const parts = line.split(": ");
    const header = parts.shift();
    const value = parts.join(": ");
    headerMap[header] = value;
  });
  return headerMap;
};

function isValidUrl(url) {
  try {
    return !!buildUrl(url);
  } catch {
    return false;
  }
}

function getPathName(url) {
  const pathname = buildUrl(url).pathname;
  return pathname[0] === "/" ? pathname : `/${pathname}`;
}

function buildUrl(url, base) {
  const supportedURL = getSupportedUrl();
  if (supportedURL) {
    try {
      return base !== undefined
        ? new supportedURL(url, base)
        : new supportedURL(url);
    } catch (error) {
      throw new Error(
        `Failed to construct URL: ${String(error)} ${JSON.stringify({
          url,
          base,
        })}`
      );
    }
  }
  if (base === undefined && !/:/.test(url)) {
    throw new Error(`Invalid URL: '${url}'`);
  }
  let doc = document;
  const anchorElement = doc.createElement("a");
  if (base !== undefined) {
    doc = document.implementation.createHTMLDocument("");
    const baseElement = doc.createElement("base");
    baseElement.href = base;
    doc.head.appendChild(baseElement);
    doc.body.appendChild(anchorElement);
  }
  anchorElement.href = url;
  return anchorElement;
}

const originalURL = URL;
let isURLSupported;

function getSupportedUrl() {
  if (isURLSupported === undefined) {
    try {
      const url = new originalURL("http://test/path");
      isURLSupported = url.href === "http://test/path";
    } catch {
      isURLSupported = false;
    }
  }
  return isURLSupported ? originalURL : undefined;
}

const computeResourceKind = (timing) => {
  const url = timing.name;
  if (!isValidUrl(url)) {
    return { type: ResourceType.OTHER, path: url, url: new URL(url) };
  }
  const path = getPathName(url);
  for (const [type, isType] of RESOURCE_TYPES) {
    if (isType(timing.initiatorType, path)) {
      return {
        type,
        path,
        url: new URL(url),
      };
    }
  }
  return {
    type: ResourceType.OTHER,
    path,
    url: new URL(url),
  };
};

/**
 * `host + path` for a URL, with the query string and fragment dropped.
 *
 * Span names are required to be low cardinality, and a raw URL is the opposite:
 * every distinct query string becomes its own name, which breaks aggregation and
 * leaks tokens/PII into a field that is indexed and displayed. The full URL is
 * still kept on the span as `http.url`.
 *
 * Returns undefined when the URL cannot be parsed, so callers can fall back to a
 * name without a target.
 */
function computeUrlHostPath(url) {
  if (!url) {
    return undefined;
  }
  try {
    const parsed = buildUrl(String(url), window.location.href);
    const host = parsed.host || "";
    let path = parsed.pathname || "";
    if (path && path[0] !== "/") {
      path = `/${path}`;
    }
    const hostPath = `${host}${path}`;
    return hostPath === "" ? undefined : hostPath;
  } catch {
    return undefined;
  }
}

/**
 * Sets `url.full`, the current semantic-convention key for a request's absolute
 * URL.
 *
 * The upstream browser instrumentations still emit the pre-1.21.0 `http.url`,
 * and `url.full` only appears on the span because the ingestion pipeline renames
 * it on the way in. Anything reading the SDK's OTLP output directly -- a plain
 * collector, an on-prem pipeline, a debug exporter -- therefore sees a span with
 * no URL under the key every current consumer looks for. Setting it at the
 * source makes the span correct on its own; the rename downstream leaves an
 * existing `url.full` alone, so nothing is overwritten.
 */
function setUrlAttributes(span, url) {
  if (!span || !url) {
    return;
  }
  span.setAttribute("url.full", String(url));
}

/**
 * OTel-shaped HTTP client span name: `{METHOD} {host}{path}`, degrading to
 * `{METHOD}` when the URL is unparseable.
 */
function computeHttpSpanName(method, url) {
  const verb = (method ? String(method) : "HTTP").toUpperCase();
  const hostPath = computeUrlHostPath(url);
  return hostPath ? `${verb} ${hostPath}` : verb;
}

const RESOURCE_PROVIDER_TYPES = {
  other: "other",
  firstParty: "first-party",
  cdn: "cdn",
  social: "social",
  analytics: "analytics",
};

function computeResourceProviderType(resource) {
  if (!isValidUrl(resource.name)) {
    return RESOURCE_PROVIDER_TYPES.other;
  }
  return getResourceType(resource.name);
}

function getResourceType(url) {
  const currentHost = window.location.hostname;
  const resourceHost = new URL(url).hostname;

  if (currentHost === resourceHost) {
    return RESOURCE_PROVIDER_TYPES.firstParty;
  } else {
    if (isCDN(resourceHost)) {
      return RESOURCE_PROVIDER_TYPES.cdn;
    }

    if (isAnalytics(resourceHost)) {
      return RESOURCE_PROVIDER_TYPES.analytics;
    }

    if (isSocial(resourceHost)) {
      return RESOURCE_PROVIDER_TYPES.social;
    }

    return RESOURCE_PROVIDER_TYPES.other;
  }
}

function isCDN(domain) {
  return domain.includes("cdn");
}

function isAnalytics(domain) {
  return domain.includes("analytics");
}

function isSocial(domain) {
  return domain.includes("social");
}

function headerCapture(type, headers, ignoreHeaders) {
  const normalizedHeaders = new Map(
    headers.map((header) => [
      header.toLowerCase(),
      header.toLowerCase().replace(/-/g, "_"),
    ])
  );

  return (span, getHeader) => {
    for (const [capturedHeader, normalizedHeader] of normalizedHeaders) {
      let value = getHeader(capturedHeader);

      if (value === undefined || ignoreHeaders.has(capturedHeader)) {
        continue;
      }

      if (capturedHeader === "x-access-token") {
        value = MASK_VALUE;
      }

      const key = `http.${type}.header.${normalizedHeader}`;

      if (typeof value === "string") {
        span.setAttribute(key, [value].toString());
      } else if (Array.isArray(value)) {
        span.setAttribute(key, value.toString());
      } else {
        span.setAttribute(key, [value].toString());
      }
    }
  };
}

const HeaderRegex = new RegExp(
  "traceparent;desc=['\"]00-([0-9a-f]{32})-([0-9a-f]{16})-01['\"]"
);

function addMatchToSpan(match, span) {
  if (match && match[1] && match[2]) {
    const traceId = match[1];
    const spanId = match[2];
    span.setAttribute("link.traceId", traceId);
    span.setAttribute("link.spanId", spanId);
  }
}

function captureTraceParent(serverTimingValues, span) {
  // getResponseHeader returns multiple Server-Timing headers concat with ', ' (note space)
  // fetch returns concat with ','.
  // split the difference
  for (let header of serverTimingValues.split(",")) {
    header = header.trim();
    const match = header.match(HeaderRegex);
    addMatchToSpan(match, span);
  }
}

module.exports = {
  getResponseHeaders,
  computeUrlHostPath,
  computeHttpSpanName,
  setUrlAttributes,
  computeResourceKind,
  computeResourceProviderType,
  headerCapture,
  captureTraceParent,
};
