/**
 * Click -> network attribution.
 *
 * The click span in tracing.js is created with `tracer.startSpan()` and never
 * made the active context, and the SDK registers no ZoneContextManager, so a
 * fetch fired from the application's own click handler has no parent to
 * inherit. Instead we remember recent clicks for a short window and stamp their
 * ids onto the network spans that *start* inside that window.
 *
 * This is attribution by time window, not a real parent edge: a request that
 * happens to start inside the window is attributed even when the click did not
 * cause it. Widening the window trades false negatives for false positives.
 */

/** How long after a click a network request is still considered caused by it. */
const DEFAULT_INTERACTION_WINDOW_MS = 1000;

/**
 * Rapid clicking means several windows can overlap, so keep a few and match on
 * the request's start time rather than tracking a single "current" click.
 */
const MAX_TRACKED_INTERACTIONS = 5;

let recentInteractions = [];

/**
 * Record a click as attributable for the next `windowMs`.
 * Returns the stored record, or undefined when the span carries no usable ids.
 */
function setActiveInteraction(span, options = {}) {
  const spanContext =
    span && typeof span.spanContext === "function"
      ? span.spanContext()
      : undefined;

  if (!spanContext || !spanContext.traceId || !spanContext.spanId) {
    return undefined;
  }

  const windowMs =
    options.windowMs != null ? options.windowMs : DEFAULT_INTERACTION_WINDOW_MS;
  const startedAt = options.startedAt != null ? options.startedAt : Date.now();

  const interaction = {
    traceId: spanContext.traceId,
    spanId: spanContext.spanId,
    name: options.name,
    startedAt,
    expiresAt: startedAt + windowMs,
  };

  recentInteractions.push(interaction);
  if (recentInteractions.length > MAX_TRACKED_INTERACTIONS) {
    recentInteractions.shift();
  }

  return interaction;
}

/**
 * The most recent interaction whose window contains `atMs`, if any.
 */
function getInteractionAt(atMs = Date.now()) {
  for (let index = recentInteractions.length - 1; index >= 0; index--) {
    const interaction = recentInteractions[index];
    if (atMs >= interaction.startedAt && atMs <= interaction.expiresAt) {
      return interaction;
    }
  }
  return undefined;
}

function clearInteractions() {
  recentInteractions = [];
}

/**
 * Stamp the attributed click onto a network span.
 *
 * `startTimeMs` must be when the request *started*, not when this runs — the
 * instrumentation hooks fire on completion, and a slow request would otherwise
 * miss its own window (or land in a later click's).
 */
function applyInteractionAttributes(span, startTimeMs) {
  if (!span || typeof span.setAttribute !== "function") {
    return false;
  }

  const interaction = getInteractionAt(
    startTimeMs != null ? startTimeMs : Date.now()
  );
  if (!interaction) {
    return false;
  }

  span.setAttribute("interaction.trace_id", interaction.traceId);
  span.setAttribute("interaction.span_id", interaction.spanId);
  if (interaction.name) {
    span.setAttribute("interaction.name", interaction.name);
  }
  return true;
}

module.exports = {
  DEFAULT_INTERACTION_WINDOW_MS,
  MAX_TRACKED_INTERACTIONS,
  setActiveInteraction,
  getInteractionAt,
  clearInteractions,
  applyInteractionAttributes,
};
