"use strict";

const { VERSION } = require("./version");

const EXPORT_INTERVAL_MS = 60000;
const METER_NAME = "mw.rum.sdk";

let enabled = false;
let meterProvider = null;
let initCounter = null;
let initDurationHistogram = null;
let exportCounter = null;
let exportBytesCounter = null;
let exportBatchSizeHistogram = null;
let mutationThrottledCounter = null;
let recordingDroppedCounter = null;
let sessionRotatedCounter = null;

function resetInstruments() {
  initCounter = null;
  initDurationHistogram = null;
  exportCounter = null;
  exportBytesCounter = null;
  exportBatchSizeHistogram = null;
  mutationThrottledCounter = null;
  recordingDroppedCounter = null;
  sessionRotatedCounter = null;
}

/**
 * Initialize lightweight SDK dogfood metrics. No-op unless config.sdkMetrics is true.
 * @returns {object|null} MeterProvider instance, or null when disabled
 */
function init(config, resource) {
  if (config.sdkMetrics !== true) {
    enabled = false;
    return null;
  }

  if (meterProvider) {
    return meterProvider;
  }

  const {
    MeterProvider,
    PeriodicExportingMetricReader,
  } = require("@opentelemetry/sdk-metrics");
  const {
    OTLPMetricExporter,
  } = require("@opentelemetry/exporter-metrics-otlp-http");

  const exporter = new OTLPMetricExporter({
    url: `${config.target}/v1/metrics`,
    headers: {
      "Content-Type": "application/json",
      Authorization: config.accountKey,
    },
    concurrencyLimit: 1,
  });

  const reader = new PeriodicExportingMetricReader({
    exporter,
    exportIntervalMillis: EXPORT_INTERVAL_MS,
  });

  meterProvider = new MeterProvider({
    resource,
    readers: [reader],
  });

  const meter = meterProvider.getMeter(METER_NAME, VERSION);

  initCounter = meter.createCounter("mw.rum.sdk.init", {
    description: "Count of successful Middleware RUM SDK initializations",
  });
  initDurationHistogram = meter.createHistogram("mw.rum.sdk.init.duration", {
    description: "Middleware RUM SDK init duration in milliseconds",
    unit: "ms",
  });
  exportCounter = meter.createCounter("mw.rum.sdk.export", {
    description: "Count of SDK signal export attempts by signal and status",
  });
  exportBytesCounter = meter.createCounter("mw.rum.sdk.export.bytes", {
    description: "Payload bytes exported by the SDK per signal",
    unit: "By",
  });
  exportBatchSizeHistogram = meter.createHistogram(
    "mw.rum.sdk.export.batch_size",
    {
      description: "Items per export batch by signal",
    }
  );
  mutationThrottledCounter = meter.createCounter(
    "mw.rum.sdk.recording.mutation_throttled",
    {
      description: "Session recording mutation rate-limit hits",
    }
  );
  recordingDroppedCounter = meter.createCounter(
    "mw.rum.sdk.recording.dropped",
    {
      description:
        "Session recording events discarded before export, by reason",
    }
  );
  sessionRotatedCounter = meter.createCounter(
    "mw.rum.sdk.recording.session_rotated",
    {
      description:
        "Session recording re-armed after a mid-page session rotation",
    }
  );

  enabled = true;
  return meterProvider;
}

/**
 * Record a successful SDK init and its duration.
 * @param {number} durationMs
 */
function recordInit(durationMs) {
  if (!enabled) return;
  initCounter.add(1);
  if (typeof durationMs === "number" && durationMs >= 0) {
    initDurationHistogram.record(durationMs);
  }
}

/**
 * Record an export attempt at a batch boundary.
 * @param {{ signal: string, status: 'ok'|'error', bytes?: number, count?: number }} opts
 */
function recordExport(opts) {
  if (!enabled || !opts || !opts.signal) return;

  const status = opts.status === "error" ? "error" : "ok";
  const attrs = { signal: opts.signal, status };

  exportCounter.add(1, attrs);

  if (typeof opts.bytes === "number" && opts.bytes >= 0) {
    exportBytesCounter.add(opts.bytes, { signal: opts.signal });
  }

  if (typeof opts.count === "number" && opts.count >= 0) {
    exportBatchSizeHistogram.record(opts.count, { signal: opts.signal });
  }
}

function recordMutationThrottled() {
  if (!enabled) return;
  mutationThrottledCounter.add(1);
}

/**
 * Record a session-recording event discarded before export.
 * @param {'hidden'|'paused'|'max_length'} reason
 */
function recordRecordingDropped(reason) {
  if (!enabled || !reason) return;
  recordingDroppedCounter.add(1, { reason });
}

function recordSessionRotated() {
  if (!enabled) return;
  sessionRotatedCounter.add(1);
}

function shutdown() {
  enabled = false;
  resetInstruments();
  const provider = meterProvider;
  meterProvider = null;
  if (provider) {
    return provider.shutdown();
  }
  return Promise.resolve();
}

function isEnabled() {
  return enabled;
}

/** @internal test helper */
function _resetForTests() {
  enabled = false;
  meterProvider = null;
  resetInstruments();
}

module.exports = {
  init,
  recordInit,
  recordExport,
  recordMutationThrottled,
  recordRecordingDropped,
  recordSessionRotated,
  shutdown,
  isEnabled,
  EXPORT_INTERVAL_MS,
  _resetForTests,
};
