const {
  DocumentLoadInstrumentation,
} = require("@opentelemetry/instrumentation-document-load");
const { isUrlIgnored } = require("@opentelemetry/core");
const { context, ROOT_CONTEXT } = require("@opentelemetry/api");
const excludedInitiatorTypes = ["beacon", "fetch", "xmlhttprequest"];

/**
 * loadEventEnd of the current navigation, on the same timeOrigin-relative
 * clock as PerformanceResourceTiming.startTime. Undefined when the browser
 * has not recorded it: no Navigation Timing 2 support, or the load event is
 * still running.
 */
function getLoadEventEnd() {
  if (typeof performance === "undefined" || !performance.getEntriesByType) {
    return undefined;
  }
  const navigation = performance.getEntriesByType("navigation")[0];
  const loadEventEnd = navigation && navigation.loadEventEnd;
  return typeof loadEventEnd === "number" && loadEventEnd > 0
    ? loadEventEnd
    : undefined;
}

class MiddlewareDocumentLoadInstrumentation extends DocumentLoadInstrumentation {
  config = {};
  _loadEventEnd = undefined;
  constructor(config = {}) {
    super(config);
    this.config = config;
  }

  _endSpan(span, performanceName, entries) {
    if (span && span.name && !span.name.includes("documentLoad")) {
      if (span.name.includes("documentFetch") && !entries.serverTiming) {
        const navEntries = performance.getEntriesByType("navigation");
        if (navEntries[0]?.serverTiming) {
          entries.serverTiming = navEntries[0].serverTiming;
        }
        for (const [key, value] of Object.entries(entries)) {
          const attributeName = `navigation.${key}`;
          span.setAttribute(attributeName, value);
        }
      }
    }
    if (span && span.name && span.name.includes("documentLoad")) {
      this._addExtraDocLoadTags(span);
    }
    return super._endSpan(span, performanceName, entries);
  }

  /**
   * Resource spans are collected in a single sweep of the performance buffer
   * after the load event, and that sweep runs late when the SDK itself is
   * injected after the page has loaded. Everything fetched in the meantime
   * (lazy chunks, fonts, third-party widgets) would otherwise be parented
   * under documentLoad and stretch its trace well past loadEventEnd.
   */
  _addResourcesSpans(rootSpan) {
    this._loadEventEnd = getLoadEventEnd();
    return super._addResourcesSpans(rootSpan);
  }

  _startedAfterLoad(resource) {
    return (
      this._loadEventEnd !== undefined &&
      typeof resource.startTime === "number" &&
      resource.startTime > this._loadEventEnd
    );
  }

  _initResourceSpan(resource, parentSpan) {
    if (
      excludedInitiatorTypes.indexOf(resource.initiatorType) !== -1 ||
      isUrlIgnored(resource.name, this.config.ignoreUrls)
    ) {
      return;
    }
    if (!this._startedAfterLoad(resource)) {
      return super._initResourceSpan(resource, parentSpan);
    }
    // Started after the load event: still reported, but as a root span of its
    // own rather than a child of documentLoad. ROOT_CONTEXT also keeps it out
    // of any server trace a <meta name="traceparent"> tied documentLoad to.
    return context.with(ROOT_CONTEXT, () =>
      super._initResourceSpan(resource, undefined)
    );
  }

  _addCustomAttributesOnResourceSpan(
    span,
    resource,
    applyCustomAttributesOnSpan
  ) {
    if (this._startedAfterLoad(resource)) {
      span.setAttribute("resource.post_load", true);
    }
    return super._addCustomAttributesOnResourceSpan(
      span,
      resource,
      applyCustomAttributesOnSpan
    );
  }

  _addExtraDocLoadTags(span) {
    if (document.referrer && document.referrer !== "") {
      span.setAttribute("document.referrer", document.referrer);
    }
    if (window.screen) {
      span.setAttribute(
        "screen.xy",
        window.screen.width + "x" + window.screen.height
      );
    }
  }
}

module.exports = MiddlewareDocumentLoadInstrumentation;
