const {
  maybeErrorToObject,
  limitLen,
  MESSAGE_LIMIT,
} = require("../packages/logs-instrumentation");

const {
  B3Propagator,
  B3InjectEncoding,
} = require("@opentelemetry/propagator-b3");
const {
  CompositePropagator,
  W3CTraceContextPropagator,
  hrTimeToMilliseconds,
} = require("@opentelemetry/core");
const {
  initSessionTracking,
  getRumSessionId,
  markActivity,
  getSessionStartTime,
} = require("./session");
const {
  computeResourceKind,
  computeResourceProviderType,
  computeUrlHostPath,
  computeHttpSpanName,
  headerCapture,
} = require("./utils/httpUtils.js");
const {
  setActiveInteraction,
  applyInteractionAttributes,
} = require("./utils/interactionContext.js");
const { toOtelSeverityNumber } = require("./utils.js");
const {
  setResourceTimingAttributes,
  setResourceStatusAttributes,
} = require("./utils/resourceTiming.js");
const {
  LongTaskInstrumentation,
} = require("@opentelemetry/instrumentation-long-task");
const { WebVitalsInstrumentation } = require("./webvitals");
const MiddlewareRecorder = require("./recording");
const { PageTrackingInstrumentation } = require("./page-tracking.js");
const { VERSION } = require("./version");
const {
  getSyntheticsTestId,
  SYNTHETICS_TEST_ID_ATTRIBUTE,
} = require("./synthetics");
const { SessionBasedSampler } = require("./SessionBasedSampler");
const { GzipOTLPTraceExporter } = require("./GzipOTLPTraceExporter.js");
const {
  MiddlewareWebSocketInstrumentation,
} = require("./MiddlewareWebSocketInstrumentation.js");
const sdkMetrics = require("./sdk-metrics");

let tracer = {};

/**
 * When a network span started, in epoch ms. The instrumentation hooks run on
 * completion, so click attribution has to look at the start time instead.
 */
function spanStartTimeMs(span) {
  return span && span.startTime
    ? hrTimeToMilliseconds(span.startTime)
    : undefined;
}

const BUFFER_MAX_SPANS = 2048;
const BUFFER_TIMEOUT = 2000;

// FIX: Single shared processor with a mutable attributes map.
// Replaces the old pattern of adding one processor per attribute per setAttributes() call.
class CustomAttributeSpanProcessor {
  constructor() {
    this._customAttributes = {};
  }

  // Called by setAttributes() to merge in new attributes — no new processor created
  updateAttributes(newAttributes) {
    Object.assign(this._customAttributes, newAttributes);
  }

  onStart(span) {
    span.setAttribute("session.id", getRumSessionId());
    for (const [key, value] of Object.entries(this._customAttributes)) {
      if (value !== undefined && value !== null) {
        span.setAttribute(key, value);
      }
    }
  }

  onEnd(span) {
    // Safety net: re-apply in case span started before setAttributes() was called
    span.setAttribute("session.id", getRumSessionId());
    for (const [key, value] of Object.entries(this._customAttributes)) {
      if (value !== undefined && value !== null) {
        span.setAttribute(key, value);
      }
    }
  }

  // This processor only decorates spans as they start and end; it buffers
  // nothing, so there is never anything to flush. Both methods still have to
  // exist and return promises: since SDK 2.0 the provider calls forceFlush and
  // shutdown on every registered processor, and a missing forceFlush made
  // provider.forceFlush() reject — which is what flushes pending spans when the
  // page is closing, so a rejection there loses the tail of every session.
  forceFlush() {
    return Promise.resolve();
  }

  shutdown() {
    return Promise.resolve();
  }
}

module.exports.CustomAttributeSpanProcessor = CustomAttributeSpanProcessor;
let sharedAttributeProcessor = null;

/**
 * Copies a longtask entry's attribution onto its span. A single attribution
 * keeps the flat `longtask.attribution.*` keys; multiple are indexed so they
 * don't overwrite each other.
 */
function setLongtaskAttribution(span, attributionList) {
  if (!Array.isArray(attributionList)) {
    return;
  }
  attributionList.forEach((attribution, index) => {
    const prefix =
      attributionList.length > 1
        ? `longtask.attribution[${index}]`
        : "longtask.attribution";
    span.setAttribute(`${prefix}.name`, attribution.name);
    span.setAttribute(`${prefix}.entry_type`, attribution.entryType);
    span.setAttribute(`${prefix}.start_time`, attribution.startTime);
    span.setAttribute(`${prefix}.duration`, attribution.duration);
    span.setAttribute(`${prefix}.container_type`, attribution.containerType);
    span.setAttribute(`${prefix}.container_src`, attribution.containerSrc);
    span.setAttribute(`${prefix}.container_id`, attribution.containerId);
    span.setAttribute(`${prefix}.container_name`, attribution.containerName);
  });
}

module.exports.setLongtaskAttribution = setLongtaskAttribution;

function getOS() {
  let userAgent = window.navigator.userAgent,
    platform = window.navigator.platform,
    macosPlatforms = ["Macintosh", "MacIntel", "MacPPC", "Mac68K"],
    windowsPlatforms = ["Win32", "Win64", "Windows", "WinCE"],
    iosPlatforms = ["iPhone", "iPad", "iPod"],
    os = null;

  if (macosPlatforms.indexOf(platform) !== -1) {
    os = "Mac OS";
  } else if (iosPlatforms.indexOf(platform) !== -1) {
    os = "iOS";
  } else if (windowsPlatforms.indexOf(platform) !== -1) {
    os = "Windows";
  } else if (/Android/.test(userAgent)) {
    os = "Android";
  } else if (!os && /Linux/.test(platform)) {
    os = "Linux";
  }

  return os;
}

let provider;
let logsExporter;
let meterProvider;
let logsInstrumentation;
let inited = false;

module.exports.init = (config) => {
  const initStartedAt = Date.now();
  const { trace, context, propagation } = require("@opentelemetry/api");
  const {
    WebTracerProvider,
    getElementXPath,
  } = require("@opentelemetry/sdk-trace-web");
  const { BatchSpanProcessor } = require("@opentelemetry/sdk-trace-base");
  const {
    registerInstrumentations,
  } = require("@opentelemetry/instrumentation");
  const {
    resourceFromAttributes,
    defaultResource,
  } = require("@opentelemetry/resources");
  const {
    ATTR_SERVICE_NAME,
    ATTR_URL_FULL,
    ATTR_HTTP_REQUEST_METHOD,
  } = require("@opentelemetry/semantic-conventions");
  const { LogsExporter } = require("../packages/logs-exporter");
  const { LogsInstrumentation } = require("../packages/logs-instrumentation");
  const MiddlewareDocumentLoadInstrumentation = require("./MiddlewareLoadInstrumentation");
  const MiddlewareXHRInstrumentaion = require("./MiddlewareXHRInstrumentation");
  const MiddlewareFetchInstrumentation = require("./MiddlewareFetchInstrumentation");

  const {
    DEFAULT_USER_INTERACTION_ELEMENT_NAME_LIMIT,
  } = require("./constants");
  const {
    getUserInteractionSpanName,
    generateId,
    jsonToString,
    normalizeContentType,
    getBrowserInfo,
  } = require("./utils.js");
  const { DeadClickTracker } = require("./deadClick");
  const { RageClickTracker } = require("./rageClick");
  const ignoreHeaders = config.ignoreHeaders;
  initSessionTracking(reinit, generateId(128), config.cookieDomain);

  const os = getOS();
  tracer = { ...tracer, ...config.tracer };

  const browserInfo = getBrowserInfo();
  const RESOURCE_ATTRS = {
    [ATTR_SERVICE_NAME]: config.serviceName,
    ["mw_agent"]: true,
    ["project.name"]: config.projectName,
    ["browser.trace"]: "true",
    ["mw.rum"]: "true",
    os,
    recording: config.recording,
    env: config.env,
    target: config.target,
    origin: window.location.origin,
    rum_origin: window.location.origin,
    "mw.rum.sdk.version": VERSION,
    "browser.name": browserInfo.browser,
    "browser.version": browserInfo.version,
    "navigator.userAgent": navigator.userAgent.toString(),
  };

  if (config.vcsCommitSHA) {
    RESOURCE_ATTRS["vcs.commit_sha"] = config.vcsCommitSHA;
  }

  if (config.vcsRepositoryURL) {
    RESOURCE_ATTRS["vcs.repository_url"] = config.vcsRepositoryURL;
  }

  const syntheticsTestId = getSyntheticsTestId();
  if (syntheticsTestId) {
    RESOURCE_ATTRS[SYNTHETICS_TEST_ID_ATTRIBUTE] = syntheticsTestId;
  }
  // SDK 2.x no longer folds the default resource into the one it is given, so
  // merging here is what keeps telemetry.sdk.* on every span.
  let resources = defaultResource().merge(
    resourceFromAttributes(RESOURCE_ATTRS)
  );

  // session.id and session.start_time have to be read when a span is exported
  // rather than when the SDK starts, because the session can rotate mid-page.
  // These getters are defined on the resource before it reaches the provider:
  // 2.x dropped the provider's public `resource` accessor, and the attributes
  // object is memoized by the resource, so getters defined on it stay put.
  Object.defineProperty(resources.attributes, "session.id", {
    get() {
      return getRumSessionId();
    },
    configurable: true,
    enumerable: true,
  });

  Object.defineProperty(resources.attributes, "session.start_time", {
    get() {
      return getSessionStartTime();
    },
    configurable: true,
    enumerable: true,
  });

  Middleware.defaultAttributes = {
    ...config.defaultAttributes,
    ...Middleware.defaultAttributes,
    "root.url": window.location.pathname,
    "page.title": document.title,
    "page.href": window.location.href,
    advanceNetworkCapture: config.advanceNetworkCapture,
  };

  sharedAttributeProcessor = new CustomAttributeSpanProcessor();

  const sampler = tracer?.sampler ?? new SessionBasedSampler();
  // Span processors are constructor-only since SDK 2.0; addSpanProcessor is gone.
  provider = new WebTracerProvider({
    resource: resources,
    sampler,
    spanProcessors: [
      new BatchSpanProcessor(
        new GzipOTLPTraceExporter({
          url: `${config.target}/v1/traces`,
          headers: {
            "Content-Type": "application/json",
            "Access-Control-Allow-Headers": "*",
            Authorization: config.accountKey,
          },
        }),
        {
          maxExportBatchSize: config.bufferSize,
          scheduledDelayMillis: config.bufferTimeout,
        }
      ),
      sharedAttributeProcessor,
    ],
  });

  trace.setGlobalTracerProvider(provider);

  if (config.tracePropagationFormat === "w3c") {
    provider.register({
      propagator: new W3CTraceContextPropagator(),
    });
  } else if (config.tracePropagationFormat === "b3") {
    provider.register({
      propagator: new CompositePropagator({
        propagators: [
          new B3Propagator(),
          new B3Propagator({ injectEncoding: B3InjectEncoding.MULTI_HEADER }),
        ],
      }),
    });
  } else {
    provider.register({
      propagator: new CompositePropagator({
        propagators: [
          new W3CTraceContextPropagator(),
          new B3Propagator(),
          new B3Propagator({ injectEncoding: B3InjectEncoding.MULTI_HEADER }),
        ],
      }),
    });
  }

  const headers = {};
  propagation.inject(context.active(), headers);

  this.setAttributes(Middleware.defaultAttributes);

  logsExporter = new LogsExporter({
    config,
    resource: resources,
    collectorUrl: `${config.target}/v1/logs`,
    maxQueueSize: BUFFER_MAX_SPANS,
    scheduledDelayMillis: BUFFER_TIMEOUT,
    projectName: config.projectName,
    serviceName: config.serviceName,
    attributes: Middleware.defaultAttributes,
  });
  logsInstrumentation = new LogsInstrumentation({
    exporter: logsExporter,
    config,
  });
  logsInstrumentation.enable(config);

  const rageClickTracker = new RageClickTracker();

  // One span per click: we keep the click span open and end it either after dead-click
  // timeout (normal click) or in the dead-click callback (add frustration.type then end).
  const pendingClickSpans = new WeakMap();

  const deadClickTracker = new DeadClickTracker(function (deadClickEvent) {
    const pending = pendingClickSpans.get(deadClickEvent);
    if (!pending) {
      return;
    }
    clearTimeout(pending.timeoutId);
    pending.span.setAttribute("frustration.type", "dead_click");
    pending.span.end();
    pendingClickSpans.delete(deadClickEvent);
  });
  deadClickTracker.startTracking();

  document.addEventListener("click", (event) => {
    const _eventNames = new Set(["click"]);
    const target = event.target;
    if (!(target instanceof HTMLElement)) {
      return undefined;
    }
    if (!target.getAttribute) {
      return undefined;
    }
    if (target.hasAttribute("disabled")) {
      return undefined;
    }
    if (!_eventNames.has(event.type)) {
      return undefined;
    }

    const deadClickConfig = config.deadClick
      ? Object.assign({}, config.deadClick)
      : {};

    let tracer = provider.getTracer("user-interaction");
    const newName = limitLen(
      getUserInteractionSpanName(
        event.type,
        target,
        DEFAULT_USER_INTERACTION_ELEMENT_NAME_LIMIT
      ),
      MESSAGE_LIMIT
    );
    let span = tracer.startSpan(newName);
    event.target.dataset.spanId = span.spanContext().spanId;
    if (rageClickTracker.isRageClick(event, config.rageClick || {})) {
      span.setAttribute("frustration.type", "rage_click");
    }
    MiddlewareRecorder.setCustomEvent("click", {
      type: event.type,
      component: "user-interaction",
    });

    deadClickTracker.trackClick(event, deadClickConfig);

    span.setAttribute("event.type", event.type);
    span.setAttribute("component", "user-interaction");
    span.setAttribute("target_element", target.tagName);
    span.setAttribute("target_xpath", getElementXPath(event.target, true));
    span.setAttribute("http.user_agent", navigator.userAgent);
    span.setAttribute("target_element_id", target.id || undefined);
    span.setAttribute("target_element_class", target.className || undefined);
    span.setAttribute("x", event.clientX);
    span.setAttribute("y", event.clientY);
    span.setAttribute("pageX", event.pageX);
    span.setAttribute("pageY", event.pageY);
    span.setAttribute("viewport.width", window.innerWidth);
    span.setAttribute("viewport.height", window.innerHeight);
    span.setAttribute("pointer.type", event.pointerType || "mouse");

    // Network requests starting in the next window are attributed to this click.
    setActiveInteraction(span, { name: newName });

    // End span after dead-click timeout; dead-click callback will end it earlier and set frustration.type if dead
    const timeoutId = setTimeout(function () {
      const pending = pendingClickSpans.get(event);
      if (pending) {
        pending.span.end();
        pendingClickSpans.delete(event);
      }
    }, deadClickConfig.timeout_ms);
    pendingClickSpans.set(event, { span, timeoutId });
  });

  const DEFAULT_IGNORE_URLS = [
    /\/v1\/metrics/i,
    /\/v1\/traces/i,
    /\/v1\/logs/i,
    ...config.ignoreUrls.map((url) => new RegExp(url)),
  ];

  const xhrInstrumenation = new MiddlewareXHRInstrumentaion({
    ignoreHeaders: config.ignoreHeaders,
    advanceNetworkCapture: config.advanceNetworkCapture,
    ignoreUrls: DEFAULT_IGNORE_URLS,
    propagateTraceHeaderCorsUrls: config.tracePropagationTargets,
    applyCustomAttributesOnSpan: (span, xhr) => {
      markActivity();
      const httpURL = span?.attributes?.[ATTR_URL_FULL];
      if (httpURL) {
        span.updateName(
          computeHttpSpanName(
            span?.attributes?.[ATTR_HTTP_REQUEST_METHOD],
            httpURL
          )
        );
      }
      span.setAttribute("event.type", "xhr");
      applyInteractionAttributes(span, spanStartTimeMs(span));
    },
  });
  const fetchInstrumenation = new MiddlewareFetchInstrumentation({
    ignoreHeaders: config.ignoreHeaders,
    advanceNetworkCapture: config.advanceNetworkCapture,
    ignoreUrls: DEFAULT_IGNORE_URLS,
    propagateTraceHeaderCorsUrls: config.tracePropagationTargets,
    clearTimingResources: true,
    applyCustomAttributesOnSpan: (span, request, response) => {
      markActivity();
      const httpURL = span?.attributes?.[ATTR_URL_FULL];
      if (httpURL) {
        span.updateName(
          computeHttpSpanName(
            request?.method ?? span?.attributes?.[ATTR_HTTP_REQUEST_METHOD],
            httpURL
          )
        );
      }
      span.setAttribute("event.type", "fetch");
      applyInteractionAttributes(span, spanStartTimeMs(span));
      if (config.advanceNetworkCapture) {
        if (request.headers) {
          headerCapture(
            "request",
            Object.keys(request.headers),
            ignoreHeaders
          )(span, (header) => request.headers?.[header]);
        }

        if (request.body) {
          if (request.body instanceof ReadableStream) {
            span.setAttribute("http.request.body", "[ReadableStream]");
          } else {
            span.setAttribute("http.request.body", request.body.toString());
          }
        }

        if (response instanceof Response) {
          if (response.headers) {
            const headerNames = [];
            response.headers.forEach((value, name) => {
              headerNames.push(name);
            });
            headerCapture(
              "response",
              headerNames,
              ignoreHeaders
            )(span, (header) => response.headers.get(header) ?? "");
          }

          const contentType = response?.headers?.get("Content-Type");
          const normalizedContentType = normalizeContentType(contentType);
          const ALLOWED_CONTENT_TYPE = new Set([
            "application/json",
            "text/plain",
            "text/x-component",
          ]);
          if (ALLOWED_CONTENT_TYPE.has(normalizedContentType)) {
            response
              .clone()
              .text()
              .then((text) => {
                const trimmed = (text || "").trim();
                if (!trimmed) return;
                let bodyValue;
                if (normalizedContentType === "text/plain") {
                  bodyValue = trimmed;
                } else {
                  try {
                    bodyValue = JSON.parse(trimmed);
                  } catch {
                    bodyValue = trimmed;
                  }
                }
                span.setAttribute(
                  "http.response.body",
                  jsonToString(bodyValue)
                );
              })
              .catch(() => {
                // Ignore
              });
          }
        }
      }
    },
  });

  const longtaskInstrumentation = new LongTaskInstrumentation({
    enabled: true,
    observerCallback: (span, info) => {
      markActivity();
      span.setAttribute("event.type", "longtask");
      span.updateName(`${span.name} ${window.location.pathname}`);
      setLongtaskAttribution(span, info.longtaskEntry.attribution);
    },
  });
  const documentLoadInstrumentation = new MiddlewareDocumentLoadInstrumentation(
    {
      applyCustomAttributesOnSpan: {
        documentLoad: (span) => {
          span.setAttribute("event.type", "load");
          const target = computeUrlHostPath(attributes["root.url"]);
          if (target) {
            span.updateName(`${span.name} ${target}`);
          }
        },
        resourceFetch: (span, resource) => {
          span.setAttribute("event.type", "resource");
          setResourceStatusAttributes(span, resource);
          setResourceTimingAttributes(span, resource);
          const computedResourceAttr = computeResourceKind(resource);
          span.setAttribute("resource.type", computedResourceAttr.type);
          span.setAttribute("resource.url_path", computedResourceAttr.path);
          span.setAttribute(
            "resource.url",
            computedResourceAttr.url.toString()
          );
          span.setAttribute("resource.url_host", computedResourceAttr.url.host);
          span.setAttribute(
            "resource.url_scheme",
            computedResourceAttr.url.protocol
          );
          span.setAttribute(
            "resource.provider.type",
            computeResourceProviderType(resource)
          );
          // PerformanceResourceTiming carries no method — browser-initiated
          // resource loads are GETs.
          span.updateName(computeHttpSpanName("GET", resource.name));
        },
      },
    }
  );

  if (config.disableNetworkInstrumentation) {
    xhrInstrumenation.disable();
    fetchInstrumenation.disable();
  }

  if (!config.longtask) {
    longtaskInstrumentation.disable();
  }

  const webVitalsInstrumentation = new WebVitalsInstrumentation();
  if (config.webVitals) {
    webVitalsInstrumentation.enable();
  } else {
    webVitalsInstrumentation.disable();
  }

  const websocketInstrumentation = new MiddlewareWebSocketInstrumentation({
    ignoreUrls: DEFAULT_IGNORE_URLS,
  });
  if (config.websocket) {
    websocketInstrumentation.enable();
  } else {
    websocketInstrumentation.disable();
  }

  const pageTrackingInstrumentation = new PageTrackingInstrumentation({
    scrollCheckpoints: config.scrollCheckpoints,
    trackSubmit: config.trackSubmit,
  });
  if (config.pageTracking) {
    pageTrackingInstrumentation.enable();
  } else {
    pageTrackingInstrumentation.disable();
  }
  const instrumentations = [
    longtaskInstrumentation,
    documentLoadInstrumentation,
    xhrInstrumenation,
    fetchInstrumenation,
    webVitalsInstrumentation,
    pageTrackingInstrumentation,
  ];

  registerInstrumentations({
    instrumentations,
  });
  if (config.recording === "1") {
    MiddlewareRecorder.init(config, provider, resources);
  }

  meterProvider = sdkMetrics.init(config, resources);
  sdkMetrics.recordInit(Date.now() - initStartedAt);
  inited = true;
};

// session.js calls this when it mints a new session id mid-page.
const reinit = () => {
  MiddlewareRecorder.onSessionRotate();
};

module.exports.setAttributes = (newAttributes = {}) => {
  Middleware.defaultAttributes = {
    ...Middleware.defaultAttributes,
    ...newAttributes,
  };

  // FIX: Instead of adding a new processor per attribute per call,
  // just update the single shared processor's internal map.
  if (sharedAttributeProcessor) {
    sharedAttributeProcessor.updateAttributes(Middleware.defaultAttributes);
  }
};

module.exports.addAction = (action, attributes = {}) => {
  if (!inited) {
    return;
  }
  const now = Date.now();
  const tracer = provider.getTracer("custom-action");
  const span = tracer.startSpan(action, { startTime: now });
  span.setAttributes(attributes);
  span.end(now);
};

module.exports.recordLog = (type, error) => {
  logsExporter.recordLog({
    severityNumber: toOtelSeverityNumber(type.toUpperCase()),
    severityText: type.toUpperCase(),
    type,
    message: error instanceof Error ? error.message : String(error),
    error:
      error instanceof Error
        ? maybeErrorToObject(error)
        : type === "error"
          ? maybeErrorToObject(new Error(String(error)))
          : undefined,
  });
};

module.exports.getSessionId = () => {
  return getRumSessionId();
};

module.exports.getTracer = (name) => {
  if (provider) {
    return provider.getTracer(name);
  }
  return null;
};

module.exports.deinit = () => {
  if (provider) {
    provider.shutdown();
    provider = null;
  }
  sdkMetrics.shutdown();
  meterProvider = null;
  if (logsInstrumentation) {
    logsInstrumentation.disable();
    logsInstrumentation = null;
  }
  // Reset singleton on deinit so a fresh init() creates a new one
  sharedAttributeProcessor = null;
  MiddlewareRecorder.deinit();
};
