class RRWebProcessor {
  events = [];
  scheduledDelayMillis = 0;
  exporter = undefined;
  timeout = undefined;

  constructor(exporter, config = {}) {
    this.scheduledDelayMillis = config.scheduledDelayMillis || 5000;
    this.exporter = exporter;

    // A batch still waiting on its timer when the page navigates away used to be
    // flushed from `unload`, which is too late for a fetch to leave the page: every
    // recording ended at the last timer flush before the navigation. `pagehide`
    // and `visibilitychange` fire early enough, and the exporter sends keepalive.
    this._onPageHide = () => this._flushAll({ keepalive: true });
    this._onVisibilityChange = () => {
      if (window.document.visibilityState === "hidden") {
        this._flushAll({ keepalive: true });
      }
    };
    window.addEventListener("pagehide", this._onPageHide);
    window.document.addEventListener(
      "visibilitychange",
      this._onVisibilityChange
    );
  }

  onMetric(event) {
    this.events.push(event);
    if (this.timeout === undefined) {
      this.timeout = setTimeout(() => {
        this.timeout = undefined;
        this._flushAll();
      }, this.scheduledDelayMillis);
    }
  }

  shutdown() {
    window.removeEventListener("pagehide", this._onPageHide);
    window.document.removeEventListener(
      "visibilitychange",
      this._onVisibilityChange
    );
    this._flushAll();
  }

  _flushAll(options) {
    clearTimeout(this.timeout);
    this.timeout = undefined;
    const eventsToExport = this.events.splice(0, this.events.length);
    if (eventsToExport.length === 0) {
      return;
    }
    this.exporter.export(eventsToExport, options);
  }
}

module.exports = RRWebProcessor;
