const {
  FetchInstrumentation,
} = require("@opentelemetry/instrumentation-fetch");

const web = require("@opentelemetry/sdk-trace-web");
const { setResourceTimingAttributes } = require("./utils/resourceTiming.js");
const { SpanStatusCode } = require("@opentelemetry/api");

class MiddlewareFetchInstrumentation extends FetchInstrumentation {
  constructor(config = {}) {
    super(config);

    const _endSpan = this._endSpan.bind(this);
    this._endSpan = (span, spanData, response) => {
      if (response.status >= 400) {
        span.setStatus({
          code: SpanStatusCode.ERROR,
        });
      }
      span.setAttribute("resource.type", "fetch");
      _endSpan(span, spanData, response);
    };
  }

  /**
   * Resource timings are read here rather than in `_endSpan` because a fetch's
   * PerformanceResourceTiming entry does not exist yet when the response
   * settles. Upstream waits OBSERVER_WAIT_TIME_MS for the PerformanceObserver
   * to deliver it and only then calls this method, so this is the first point
   * at which the entry can actually be found. Reading it any earlier matched
   * nothing, which is why most fetch spans carried no `resource.*` timings at
   * all.
   *
   * `endTime` is the performance-clock end time upstream captured when the
   * response settled, which is what the entry has to be matched against.
   */
  _findResourceAndAddNetworkEvents(span, spanData, endTime) {
    let resources = spanData.entries;

    if (!resources.length) {
      // Fallback - either the observer is unavailable or it did not collect
      // enough information within the wait window.
      resources =
        typeof performance !== "undefined" && performance.getEntriesByType
          ? performance.getEntriesByType("resource")
          : [];
    }

    if (resources.length) {
      // Runs before super, which marks the entry as used; afterwards the same
      // lookup would skip it.
      const resource = web.getResource(
        spanData.spanUrl,
        spanData.startTime,
        endTime,
        resources,
        this._usedResources,
        "fetch"
      );

      if (resource.mainRequest) {
        setResourceTimingAttributes(span, resource.mainRequest);
      }
    }

    return super._findResourceAndAddNetworkEvents(span, spanData, endTime);
  }
}

module.exports = MiddlewareFetchInstrumentation;
