const {
  getClickEventTargetElement,
  isDefinitelyNonInteractive,
} = require("./utils.js");

const DEFAULT_RAGE_CLICK_THRESHOLD_PX = 30;
const DEFAULT_RAGE_CLICK_TIMEOUT_MS = 1000;
const DEFAULT_RAGE_CLICK_CLICK_COUNT = 4;
const DEFAULT_RAGE_CLICK_INTERACTIVE_ELEMENTS_ONLY = false;

function RageClickTracker() {
  this.clicks = [];
}
/**
 * Determines if a click event is part of a rage click sequence.
 * @param {Event} event - the original click event.
 * @param {Object} options - configuration options for rage click detection.
 * @param {number} [options.threshold_px] - max distance (px) between clicks in the sequence.
 * @param {number} [options.timeout_ms] - max time (ms) between clicks in the sequence.
 * @param {number} [options.click_count] - number of clicks required to count as rage click.
 * @param {boolean} [options.interactive_elements_only] - if true, only consider clicks on interactive elements.
 * @returns {boolean} - true if the click is considered a rage click, false otherwise.
 */
RageClickTracker.prototype.isRageClick = function (event, options) {
  options = options || {};
  const thresholdPx =
    options.threshold_px != null
      ? options.threshold_px
      : DEFAULT_RAGE_CLICK_THRESHOLD_PX;
  const timeoutMs =
    options.timeout_ms != null
      ? options.timeout_ms
      : DEFAULT_RAGE_CLICK_TIMEOUT_MS;
  const clickCount =
    options.click_count != null
      ? options.click_count
      : DEFAULT_RAGE_CLICK_CLICK_COUNT;
  const interactiveElementsOnly =
    options.interactive_elements_only != null
      ? options.interactive_elements_only
      : DEFAULT_RAGE_CLICK_INTERACTIVE_ELEMENTS_ONLY;

  if (interactiveElementsOnly) {
    const target = getClickEventTargetElement(event);
    if (!target || isDefinitelyNonInteractive(target)) {
      return false;
    }
  }

  const timestamp = Date.now();
  const x = event.pageX;
  const y = event.pageY;

  const lastClick = this.clicks[this.clicks.length - 1];
  if (
    lastClick &&
    timestamp - lastClick.timestamp < timeoutMs &&
    Math.sqrt(Math.pow(x - lastClick.x, 2) + Math.pow(y - lastClick.y, 2)) <
      thresholdPx
  ) {
    this.clicks.push({ x: x, y: y, timestamp: timestamp });
    if (this.clicks.length >= clickCount) {
      this.clicks = [];
      return true;
    }
  } else {
    this.clicks = [{ x: x, y: y, timestamp: timestamp }];
  }
  return false;
};

module.exports = {
  RageClickTracker,
  DEFAULT_RAGE_CLICK_THRESHOLD_PX,
  DEFAULT_RAGE_CLICK_TIMEOUT_MS,
  DEFAULT_RAGE_CLICK_CLICK_COUNT,
  DEFAULT_RAGE_CLICK_INTERACTIVE_ELEMENTS_ONLY,
};
